PathwayData.put("data/reading_writing/units/L03U2.json",{"strand":"reading_writing","level":3,"cefr":"A2a","unit":2,"theme":"Helping Hands","essential_question":"How can we help the people around us?","schema_version":"1.0","core_words":["volunteer","kindness","donate","collect","elderly","visit","clean up","charity","generous","grateful","care for","need","offer","team"],"recycled_words":["kind","help","neighbor","park","proud","because","so","thank you","evidence","plan","sign","together","family"],"rubrics":[{"id":"RW-RUBRIC-5T","title":"Analytic writing rubric","traits":[{"name":"Ideas","name_ar":"الأفكار","bands":[{"score":4,"descriptor":"My ideas are clear, interesting and fully developed with strong details.","descriptor_ar":"أفكاري واضحة وممتعة ومدعومة بتفاصيل قوية."},{"score":3,"descriptor":"My ideas are clear and have enough details.","descriptor_ar":"أفكاري واضحة ومعها تفاصيل كافية."},{"score":2,"descriptor":"My main idea is there but needs more details.","descriptor_ar":"فكرتي الرئيسية موجودة لكنها تحتاج إلى تفاصيل أكثر."},{"score":1,"descriptor":"My ideas are unclear or very few.","descriptor_ar":"أفكاري غير واضحة أو قليلة جدًا."}]},{"name":"Organization","name_ar":"التنظيم","bands":[{"score":4,"descriptor":"Clear beginning, middle and end; ideas flow with linking words.","descriptor_ar":"بداية ووسط ونهاية واضحة، والأفكار مترابطة بكلمات الربط."},{"score":3,"descriptor":"Clear order with some linking words.","descriptor_ar":"ترتيب واضح مع بعض كلمات الربط."},{"score":2,"descriptor":"Some order, but parts are mixed up.","descriptor_ar":"يوجد بعض الترتيب لكن بعض الأجزاء غير مرتبة."},{"score":1,"descriptor":"Ideas are not in order.","descriptor_ar":"الأفكار غير مرتبة."}]},{"name":"Vocabulary","name_ar":"المفردات","bands":[{"score":4,"descriptor":"I use exact, varied words, including new unit words, correctly.","descriptor_ar":"أستخدم كلمات دقيقة ومتنوعة، منها كلمات الوحدة الجديدة، بشكل صحيح."},{"score":3,"descriptor":"I use some new words correctly.","descriptor_ar":"أستخدم بعض الكلمات الجديدة بشكل صحيح."},{"score":2,"descriptor":"I use simple words; some are repeated or wrong.","descriptor_ar":"أستخدم كلمات بسيطة، وبعضها مكرر أو غير صحيح."},{"score":1,"descriptor":"I use very few words; the meaning is hard to understand.","descriptor_ar":"أستخدم كلمات قليلة جدًا ويصعب فهم المعنى."}]},{"name":"Sentence fluency","name_ar":"سلاسة الجمل","bands":[{"score":4,"descriptor":"My sentences are complete, varied in length and easy to read aloud.","descriptor_ar":"جملي كاملة ومتنوعة الطول وسهلة القراءة بصوت عالٍ."},{"score":3,"descriptor":"Most sentences are complete, with some variety.","descriptor_ar":"معظم جملي كاملة مع بعض التنويع."},{"score":2,"descriptor":"Many sentences are short or start the same way.","descriptor_ar":"كثير من جملي قصيرة أو تبدأ بالطريقة نفسها."},{"score":1,"descriptor":"Sentences are incomplete or run together.","descriptor_ar":"جملي ناقصة أو متداخلة."}]},{"name":"Conventions","name_ar":"قواعد الكتابة","bands":[{"score":4,"descriptor":"Capitals, punctuation, spelling and grammar are almost always correct.","descriptor_ar":"الحروف الكبيرة وعلامات الترقيم والإملاء والقواعد صحيحة دائمًا تقريبًا."},{"score":3,"descriptor":"A few mistakes that do not affect meaning.","descriptor_ar":"أخطاء قليلة لا تؤثر في المعنى."},{"score":2,"descriptor":"Several mistakes; the meaning is sometimes unclear.","descriptor_ar":"عدة أخطاء، والمعنى أحيانًا غير واضح."},{"score":1,"descriptor":"Many mistakes make it hard to read.","descriptor_ar":"أخطاء كثيرة تجعل القراءة صعبة."}]}]}],"lessons":[{"id":"RW-L03-U2-LS1","title":"Word Power: Helping Hands","lesson_type":"vocabulary","objectives":["read, say and use 14 words about helping others and 3 Tier 2 words (community, trait, responsible)","use the suffixes -ful (full of) and -less (without) to build and understand new words","talk about ways to help people in our community"],"objectives_ar":["قراءة ونطق واستخدام 14 كلمة عن مساعدة الآخرين و3 كلمات أكاديمية (community, trait, responsible).","استخدام اللاحقتين -ful (مليء بـ) و-less (بدون) لبناء كلمات جديدة وفهمها.","التحدث عن طرق مساعدة الناس في مجتمعنا."],"success_criteria":["I can read and use the helping words in sentences.","I can explain a word with -ful or -less (careful = full of care).","I can name three ways to help in my community."],"success_criteria_ar":["أستطيع قراءة كلمات المساعدة واستخدامها في جمل.","أستطيع شرح كلمة فيها -ful أو -less.","أستطيع ذكر ثلاث طرق للمساعدة في مجتمعي."],"map_area":"Vocabulary: Acquisition and Use","vocabulary":[{"word":"volunteer","pos":"noun / verb","ipa":"/ˌvɑlənˈtɪr/","definition":"a person who helps without being paid; to offer to help for free","arabic":"متطوع / يتطوّع","example":"Noura is a volunteer at the park clean-up.","image_id":"IMG-RW-L03-U2-LS1-V01","audio_id":"AUD-RW-L03-U2-LS1-V01","tier":"core"},{"word":"kindness","pos":"noun","ipa":"/ˈkaɪndnəs/","definition":"being kind and caring to others","arabic":"لطف","example":"A smile is a small act of kindness.","image_id":"IMG-RW-L03-U2-LS1-V02","audio_id":"AUD-RW-L03-U2-LS1-V02","tier":"core"},{"word":"donate","pos":"verb","ipa":"/ˈdoʊneɪt/","definition":"to give money, food or things to help people","arabic":"يتبرّع","example":"We donate warm coats in winter.","image_id":"IMG-RW-L03-U2-LS1-V03","audio_id":"AUD-RW-L03-U2-LS1-V03","tier":"core"},{"word":"collect","pos":"verb","ipa":"/kəˈlɛkt/","definition":"to bring things together in one place","arabic":"يجمع","example":"The volunteers collect plastic bottles.","image_id":"IMG-RW-L03-U2-LS1-V04","audio_id":"AUD-RW-L03-U2-LS1-V04","tier":"core"},{"word":"elderly","pos":"adjective","ipa":"/ˈɛldərli/","definition":"old (a polite word for old people)","arabic":"مُسِنّ","example":"Mrs. Amal is an elderly neighbor.","image_id":"IMG-RW-L03-U2-LS1-V05","audio_id":"AUD-RW-L03-U2-LS1-V05","tier":"core"},{"word":"visit","pos":"verb","ipa":"/ˈvɪzɪt/","definition":"to go to see a person or a place","arabic":"يزور","example":"We visit Grandpa every Friday.","image_id":"IMG-RW-L03-U2-LS1-V06","audio_id":"AUD-RW-L03-U2-LS1-V06","tier":"core"},{"word":"clean up","pos":"verb","ipa":"/klin ʌp/","definition":"to make a place clean and tidy","arabic":"ينظّف (مكانًا)","example":"Let's clean up the park.","image_id":"IMG-RW-L03-U2-LS1-V07","audio_id":"AUD-RW-L03-U2-LS1-V07","tier":"core"},{"word":"charity","pos":"noun","ipa":"/ˈtʃærəti/","definition":"a group that helps people in need; giving to people in need","arabic":"جمعية خيرية / صدقة","example":"The charity gives food to families.","image_id":"IMG-RW-L03-U2-LS1-V08","audio_id":"AUD-RW-L03-U2-LS1-V08","tier":"core"},{"word":"generous","pos":"adjective","ipa":"/ˈdʒɛnərəs/","definition":"happy to give and share","arabic":"كريم","example":"Mrs. Amal is generous; she shares her juice.","image_id":"IMG-RW-L03-U2-LS1-V09","audio_id":"AUD-RW-L03-U2-LS1-V09","tier":"core"},{"word":"grateful","pos":"adjective","ipa":"/ˈɡreɪtfəl/","definition":"feeling thankful","arabic":"ممتنّ","example":"I am grateful for my family.","image_id":"IMG-RW-L03-U2-LS1-V10","audio_id":"AUD-RW-L03-U2-LS1-V10","tier":"core"},{"word":"care for","pos":"verb","ipa":"/kɛr fɔr/","definition":"to look after someone or something","arabic":"يعتني بـ","example":"Faris cares for his baby sister.","image_id":"IMG-RW-L03-U2-LS1-V11","audio_id":"AUD-RW-L03-U2-LS1-V11","tier":"core"},{"word":"need","pos":"noun","ipa":"/nid/","definition":"something a person must have (people in need = people who do not have what they need)","arabic":"حاجة","example":"We help people in need.","image_id":"IMG-RW-L03-U2-LS1-V12","audio_id":"AUD-RW-L03-U2-LS1-V12","tier":"core"},{"word":"offer","pos":"verb","ipa":"/ˈɔfər/","definition":"to say you will give or do something","arabic":"يعرض / يقدّم","example":"Omar offers to carry the bags.","image_id":"IMG-RW-L03-U2-LS1-V13","audio_id":"AUD-RW-L03-U2-LS1-V13","tier":"core"},{"word":"team","pos":"noun","ipa":"/tim/","definition":"a group of people who work together","arabic":"فريق","example":"Our clean-up team has ten volunteers.","image_id":"IMG-RW-L03-U2-LS1-V14","audio_id":"AUD-RW-L03-U2-LS1-V14","tier":"core"},{"word":"community","pos":"noun","ipa":"/kəˈmjunəti/","definition":"the people who live in one area, like a neighborhood","arabic":"مجتمع","example":"Our community has a park, a mosque and a school.","image_id":"IMG-RW-L03-U2-LS1-V15","audio_id":"AUD-RW-L03-U2-LS1-V15","tier":"tier2"},{"word":"trait","pos":"noun","ipa":"/treɪt/","definition":"a word that tells what a person is like inside (kind, brave, honest)","arabic":"صفة (في الشخصية)","example":"Kindness is Noura's best trait.","image_id":"IMG-RW-L03-U2-LS1-V16","audio_id":"AUD-RW-L03-U2-LS1-V16","tier":"tier2"},{"word":"responsible","pos":"adjective","ipa":"/rɪˈspɑnsəbəl/","definition":"doing the jobs you should do without being told","arabic":"مسؤول","example":"A responsible student finishes his work.","image_id":"IMG-RW-L03-U2-LS1-V17","audio_id":"AUD-RW-L03-U2-LS1-V17","tier":"tier2"}],"explanation":{"text":"A **suffix** is a small word part added to the **end** of a word. It changes the meaning.\n\n**-ful** means **full of** or **with**: *help + ful = **helpful** (full of help)*. **-less** means **without**: *help + less = **helpless** (without help)*.\n\nMany words have a **-ful** and a **-less** partner, and they are **opposites**: *careful ↔ careless*. To find the meaning: cover the suffix, read the **base word**, then add *full of* or *without*.","examples":["**help → helpful** (full of help): *Omar is helpful.* · **helpless** (without help; not able to help yourself): *A baby bird is helpless.*","**care → careful** (with care) ↔ **careless** (without care).","**hope → hopeful** (full of hope) ↔ **hopeless** (without hope).","**use → useful** (has a use) ↔ **useless** (without a use).","**thank → thankful** (full of thanks) = **grateful**.","**fear → fearless** (without fear) = brave.","**color → colorful** (full of colors): *Noura's sign is colorful.*","**cheer → cheerful** (full of cheer): *Mrs. Amal is always cheerful.*","**home → homeless** (without a home): *The charity helps homeless families.*"],"common_errors":["✗ helpfull → ✓ helpful (The suffix **-ful** has only **one l**.)","✗ carefully means without care. → ✓ carefully means with care; carelessly means without care. (-ful = **with**, -less = **without**.)","✗ He is a fearful boy. (meaning brave) → ✓ He is a fearless boy. (Brave = **without** fear = fearless.)","✗ The volunteers collects bottles. → ✓ The volunteers collect bottles. (Many volunteers → **collect**.)","✗ Mrs. Amal is olderly. → ✓ Mrs. Amal is elderly. (The word is **elderly**.)","✗ We donated to the charity some coats. → ✓ We donated some coats to the charity. (donate + thing + **to** + person/group.)","✗ I am grateful to my teacher for help me. → ✓ I am grateful to my teacher for helping me. (for + **-ing**.)"],"arabic":"اللاحقة (suffix) جزء صغير يُضاف إلى آخر الكلمة فيغيّر معناها.\n\n-ful تعني «مليء بـ» أو «فيه»: helpful = مفيد/مساعد، و-less تعني «بدون»: helpless = عاجز (بلا مساعدة).\n\nكثير من الكلمات لها شريك بـ -ful وآخر بـ -less وهما متضادان: careful (حذر) ↔ careless (مهمل).\n\nلمعرفة المعنى: غطِّ اللاحقة واقرأ الكلمة الأصلية ثم أضف «مليء بـ» أو «بدون». وانتبه: -ful بحرف l واحد فقط."},"video":{"script":[{"time":"00:00–00:20","narration":"Helping hands make a happy community! Let's meet the volunteers.","on_screen":"Helping Hands","visual":"Children in volunteer vests wave in a neighborhood with a mosque, houses and a park."},{"time":"00:20–01:00","narration":"Volunteers collect, clean up, donate and visit. They care for elderly people and people in need.","on_screen":"volunteer · collect · clean up · donate · visit · care for · elderly · need","visual":"Quick scenes: picking up bottles, packing a charity box, visiting Mrs. Amal."},{"time":"01:00–01:30","narration":"Kind, generous, grateful – a team of helpers!","on_screen":"kindness · generous · grateful · team · offer · charity","visual":"Mrs. Amal hands out juice; children say thank you with hands on hearts."},{"time":"01:30–02:30","narration":"Add -ful: full of! Add -less: without! help → helpful, helpless. care → careful, careless.","on_screen":"-ful = full of · -less = without","visual":"A word machine adds suffix blocks to base words; meanings pop out."},{"time":"02:30–03:00","narration":"Cover the suffix, read the base word, add 'full of' or 'without'. Try: hopeful!","on_screen":"Cover → base → meaning","visual":"A hand covers '-ful'; 'hope' glows; the meaning appears."}],"captions_ar":["الأيادي المساعدة تصنع مجتمعًا سعيدًا! لنتعرف على المتطوعين.","المتطوعون يجمعون وينظفون ويتبرعون ويزورون، ويعتنون بالمسنين والمحتاجين.","لطفاء وكرماء وممتنون… فريق من المساعدين!","أضف -ful تعني «مليء بـ»، وأضف -less تعني «بدون»!","غطِّ اللاحقة، واقرأ الكلمة الأصلية، ثم أضف «مليء بـ» أو «بدون». جرّب: hopeful!"],"voice":"Narrator: American English, warm female teacher, speed 0.90. Noura (the Writer): confident, kind voice."},"texts":[],"activities":[{"id":"RW-L03-U2-LS1-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Choose the correct word.","instructions_ar":"اختر الكلمة الصحيحة.","items":[{"q":"A person who helps without being paid is a ___.","answer":"volunteer","explanation":"Volunteer = helps for free.","explanation_ar":"متطوع.","options":["charity","volunteer","need","trait"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"Our class will ___ old books to the school library.","answer":"donate","explanation":"Give to help = donate.","explanation_ar":"نتبرّع.","options":["visit","care for","clean up","donate"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"Mrs. Amal is 80 years old. She is ___.","answer":"elderly","explanation":"Old (polite) = elderly.","explanation_ar":"مسنّة.","options":["generous","responsible","grateful","elderly"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"The children ___ bottles and put them in the recycling bin.","answer":"collect","explanation":"Bring together = collect.","explanation_ar":"يجمعون.","options":["donate","offer","collect","visit"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"Thank you for your help! I am very ___.","answer":"grateful","explanation":"Thankful = grateful.","explanation_ar":"ممتن.","options":["grateful","careless","elderly","helpless"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"Omar ___ to carry Mrs. Amal's shopping bags.","answer":"offers","explanation":"Say you will do it = offer.","explanation_ar":"يعرض.","options":["offers","donates","collects","needs"],"dok":1,"skill":"vocabulary","stage":"controlled"}]},{"id":"RW-L03-U2-LS1-A2","type":"mcq","stage":"guided","instructions":"Guided practice: Suffixes -ful and -less. Choose.","instructions_ar":"اللاحقتان -ful و-less: اختر.","items":[{"q":"*Careless* means ___.","answer":"without care","explanation":"-less = without.","explanation_ar":"بدون عناية.","options":["full of care","without care","very old","very kind"],"dok":1,"skill":"suffixes","stage":"guided"},{"q":"*Hopeful* means ___.","answer":"full of hope","explanation":"-ful = full of.","explanation_ar":"مليء بالأمل.","options":["without hope","very late","full of hope","a little sad"],"dok":1,"skill":"suffixes","stage":"guided"},{"q":"Which word means *without fear*?","answer":"fearless","explanation":"fear + less.","explanation_ar":"fearless.","options":["fearful","fearless","careful","useful"],"dok":1,"skill":"suffixes","stage":"guided"},{"q":"What is the opposite of *useful*?","answer":"useless","explanation":"useful ↔ useless.","explanation_ar":"useless.","options":["useless","usefull","user","used"],"dok":2,"skill":"suffixes","stage":"guided"},{"q":"Which spelling of the word that means *full of help* is correct?","answer":"helpful","explanation":"-ful has one l.","explanation_ar":"helpful.","options":["helpfull","helpfol","helpful","helpfoll"],"dok":1,"skill":"spelling","stage":"guided"},{"q":"*Lama dropped her ice cream because she was not careful.* Which word could replace *not careful*?","answer":"careless","explanation":"not careful = careless.","explanation_ar":"careless.","options":["carefully","cheerful","thankful","careless"],"dok":2,"skill":"suffixes in context","stage":"guided"}]},{"id":"RW-L03-U2-LS1-A3","type":"gap_fill","stage":"freer","instructions":"Freer practice: Use the word bank.","instructions_ar":"استخدم بنك الكلمات.","items":[{"q":"Our ________ has a park, a mosque, a school and many families.","answer":"community","explanation":"People in one area.","explanation_ar":"مجتمع.","stage":"freer"},{"q":"Kindness is my brother's best ________.","answer":"trait","explanation":"What a person is like inside.","explanation_ar":"صفة.","stage":"freer"},{"q":"A ________ student does his homework without being told.","answer":"responsible","explanation":"Does his jobs.","explanation_ar":"مسؤول.","stage":"freer"},{"q":"The ________ gives food baskets to families in need.","answer":"charity","explanation":"A group that helps people in need.","explanation_ar":"الجمعية الخيرية.","stage":"freer"},{"q":"Mrs. Amal is ________; she always shares her juice and dates.","answer":"generous","explanation":"Happy to give.","explanation_ar":"كريمة.","stage":"freer"},{"q":"Faris helps to ________ his baby sister Dana when Mom is busy.","answer":"care for","explanation":"Look after.","explanation_ar":"يعتني بـ.","stage":"freer"}]},{"id":"RW-L03-U2-LS1-A4","type":"open","stage":"production","instructions":"Writing: Write with the new words.","instructions_ar":"اكتب باستخدام الكلمات الجديدة.","items":[{"q":"Write a sentence with *helpful*.","answer":"My father is helpful; he fixes our neighbor's door.","explanation":"Use helpful correctly.","explanation_ar":"استخدم helpful.","dok":1,"skill":"suffixes","stage":"production"},{"q":"Write a sentence with *careless* and one with *careful*.","answer":"I was careless and broke a cup. Now I am careful with cups.","explanation":"Opposites with suffixes.","explanation_ar":"متضادان باللاحقة.","dok":2,"skill":"suffixes","stage":"production"},{"q":"Write two ways volunteers can help an elderly neighbor.","answer":"They can visit her and carry her shopping.","explanation":"Two ways.","explanation_ar":"طريقتان.","dok":2,"skill":"community","stage":"production"},{"q":"What is one way YOU can help your community? Why is it important?","answer":"I can collect litter in the park because a clean park is safe for everyone.","explanation":"Idea + because.","explanation_ar":"فكرة + because.","dok":3,"skill":"opinion","stage":"production"}]}],"game":{"name":"Suffix Switch","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Word workshop: a base word sits on a conveyor belt; the child drags -ful or -less onto it, hears the new word and chooses its meaning. Correct words build a 'Helping Hands' badge.","Teams get a pile of base-word cards and suffix cards.","In 3 minutes, teams build as many real words as they can.","For each word, the team writes the meaning (full of… / without…).","Teams read their words; other teams check that each is a real word.","Real word + correct meaning = 1 point; a helping sentence = bonus point."],"data":[]},"exit_quiz":[{"q":"Which word means *a group of people who work together*?","answer":"team","explanation":"Team = group working together.","explanation_ar":"فريق.","options":["trait","team","need","charity"],"dok":1,"skill":"vocabulary"},{"q":"The suffix *-less* means ___.","answer":"without","explanation":"-less = without.","explanation_ar":"بدون.","options":["without","full of","again","not yet"],"dok":1,"skill":"suffixes"},{"q":"The suffix *-ful* means ___.","answer":"full of","explanation":"-ful = full of.","explanation_ar":"مليء بـ.","options":["without","before","full of","under"],"dok":1,"skill":"suffixes"},{"q":"*We visit Grandpa every Friday.* *Visit* means ___.","answer":"go to see","explanation":"Visit = go to see.","explanation_ar":"نزور.","options":["give money to","go to see","clean up","forget"],"dok":1,"skill":"vocabulary"},{"q":"Which sentence uses *generous* correctly?","answer":"The generous boy shared his lunch with a friend.","explanation":"Generous = happy to share.","explanation_ar":"استخدام صحيح.","options":["The generous boy took all the toys.","The generous boy shared his lunch with a friend.","The generous boy never shares.","The generous boy is very old."],"dok":2,"skill":"usage"},{"q":"*The broken pencil is useless.* What does *useless* mean here?","answer":"it cannot be used","explanation":"use + less = without a use.","explanation_ar":"لا فائدة منه.","options":["it cannot be used","it is very useful","it is new","it is colorful"],"dok":2,"skill":"suffixes in context"},{"q":"Which word has the opposite meaning of *hopeful*?","answer":"hopeless","explanation":"hopeful ↔ hopeless.","explanation_ar":"hopeless.","options":["hopefull","hoping","hoped","hopeless"],"dok":2,"skill":"suffixes"},{"q":"Which sentence about the clean-up is correct?","answer":"The volunteers collect bottles in the park.","explanation":"Many volunteers → collect.","explanation_ar":"صحيحة.","options":["The volunteers collects bottles in the park.","The volunteer collect bottles in the park.","The volunteers collect bottles in the park.","The volunteers collecting bottles in the park."],"dok":2,"skill":"grammar"},{"q":"Why is it useful to know the meaning of *-ful* and *-less*?","answer":"You can understand many new words by looking at the base word and the suffix.","explanation":"Suffixes unlock meanings.","explanation_ar":"لفهم كلمات جديدة كثيرة.","options":["You can understand many new words by looking at the base word and the suffix.","They make words shorter.","They only work with names.","They tell you the time."],"dok":3,"skill":"strategy"},{"q":"A *responsible* volunteer ___.","answer":"comes on time and finishes the job","explanation":"Responsible = does what they should.","explanation_ar":"يأتي في الوقت وينهي العمل.","options":["forgets the meeting","leaves litter in the park","plays all day","comes on time and finishes the job"],"dok":3,"skill":"apply"}],"images":[{"id":"IMG-RW-L03-U2-LS1-V01","prompt":"Picture for the word 'volunteer': children in matching volunteer vests"},{"id":"IMG-RW-L03-U2-LS1-V02","prompt":"Picture for the word 'kindness': a child holding a door for an elderly man"},{"id":"IMG-RW-L03-U2-LS1-V03","prompt":"Picture for the word 'donate': a box of clothes labelled 'donations'"},{"id":"IMG-RW-L03-U2-LS1-V04","prompt":"Picture for the word 'collect': children putting bottles into a bag"},{"id":"IMG-RW-L03-U2-LS1-V05","prompt":"Picture for the word 'elderly': an elderly woman with a cane smiling"},{"id":"IMG-RW-L03-U2-LS1-V06","prompt":"Picture for the word 'visit': a family at a grandparent's door"},{"id":"IMG-RW-L03-U2-LS1-V07","prompt":"Picture for the word 'clean up': children with gloves picking up litter"},{"id":"IMG-RW-L03-U2-LS1-V08","prompt":"Picture for the word 'charity': a charity truck with boxes of food"},{"id":"IMG-RW-L03-U2-LS1-V09","prompt":"Picture for the word 'generous': a woman handing out cups of juice"},{"id":"IMG-RW-L03-U2-LS1-V10","prompt":"Picture for the word 'grateful': a child with hands on heart saying thank you"},{"id":"IMG-RW-L03-U2-LS1-V11","prompt":"Picture for the word 'care for': a boy feeding a baby"},{"id":"IMG-RW-L03-U2-LS1-V12","prompt":"Picture for the word 'need': a family receiving a food basket"},{"id":"IMG-RW-L03-U2-LS1-V13","prompt":"Picture for the word 'offer': a boy holding out his hands to carry shopping"},{"id":"IMG-RW-L03-U2-LS1-V14","prompt":"Picture for the word 'team': a group of children high-fiving"},{"id":"IMG-RW-L03-U2-LS1-V15","prompt":"Picture for the word 'community': a neighborhood map with houses, a mosque and a park"},{"id":"IMG-RW-L03-U2-LS1-V16","prompt":"Picture for the word 'trait': a heart, a lion and a shield icons"},{"id":"IMG-RW-L03-U2-LS1-V17","prompt":"Picture for the word 'responsible': a child feeding a pet on time"},{"id":"IMG-RW-L03-U2-LS1-01","prompt":"Children help their community in a park, near a mosque and with elderly neighbors."},{"id":"IMG-RW-L03-U2-LS1-02","prompt":"A word machine adding -ful and -less to 'help'."},{"id":"IMG-RW-L03-U2-LS1-03","prompt":"A classroom tree with paper-hand leaves."}],"audio":[{"id":"AUD-RW-L03-U2-LS1-V01","script":"volunteer. Noura is a volunteer at the park clean-up."},{"id":"AUD-RW-L03-U2-LS1-V02","script":"kindness. A smile is a small act of kindness."},{"id":"AUD-RW-L03-U2-LS1-V03","script":"donate. We donate warm coats in winter."},{"id":"AUD-RW-L03-U2-LS1-V04","script":"collect. The volunteers collect plastic bottles."},{"id":"AUD-RW-L03-U2-LS1-V05","script":"elderly. Mrs. Amal is an elderly neighbor."},{"id":"AUD-RW-L03-U2-LS1-V06","script":"visit. We visit Grandpa every Friday."},{"id":"AUD-RW-L03-U2-LS1-V07","script":"clean up. Let's clean up the park."},{"id":"AUD-RW-L03-U2-LS1-V08","script":"charity. The charity gives food to families."},{"id":"AUD-RW-L03-U2-LS1-V09","script":"generous. Mrs. Amal is generous; she shares her juice."},{"id":"AUD-RW-L03-U2-LS1-V10","script":"grateful. I am grateful for my family."},{"id":"AUD-RW-L03-U2-LS1-V11","script":"care for. Faris cares for his baby sister."},{"id":"AUD-RW-L03-U2-LS1-V12","script":"need. We help people in need."},{"id":"AUD-RW-L03-U2-LS1-V13","script":"offer. Omar offers to carry the bags."},{"id":"AUD-RW-L03-U2-LS1-V14","script":"team. Our clean-up team has ten volunteers."},{"id":"AUD-RW-L03-U2-LS1-V15","script":"community. Our community has a park, a mosque and a school."},{"id":"AUD-RW-L03-U2-LS1-V16","script":"trait. Kindness is Noura's best trait."},{"id":"AUD-RW-L03-U2-LS1-V17","script":"responsible. A responsible student finishes his work."},{"id":"AUD-RW-L03-U2-LS1-VID","script":"Helping hands make a happy community! Let's meet the volunteers. Volunteers collect, clean up, donate and visit. They care for elderly people and people in need. Kind, generous, grateful – a team of helpers! Add -ful: full of! Add -less: without! help → helpful, helpless. care → careful, careless. Cover the suffix, read the base word, add 'full of' or 'without'. Try: hopeful!"}]},{"id":"RW-L03-U2-LS2","title":"The Saturday Clean-Up","lesson_type":"close_reading","objectives":["read a story of about 230 words and retell the main events in order","explain how characters' actions cause the next events in the story (cause → effect)","answer literal, inferential and evaluative questions with evidence"],"objectives_ar":["قراءة قصة من نحو 230 كلمة وإعادة سرد أحداثها الرئيسية بالترتيب.","شرح كيف تؤدي أفعال الشخصيات إلى الأحداث التالية في القصة (سبب ← نتيجة).","الإجابة عن أسئلة حرفية واستنتاجية وتقييمية مع الدليل."],"success_criteria":["I can retell the story in order.","I can explain how one action leads to the next event.","I can support my answers with words from the story."],"success_criteria_ar":["أستطيع إعادة سرد القصة بالترتيب.","أستطيع شرح كيف يؤدي فعلٌ إلى الحدث التالي.","أستطيع دعم إجاباتي بكلمات من القصة."],"map_area":"Literary Text: Key Ideas and Details","vocabulary":[{"word":"frown","pos":"verb","ipa":"/fraʊn/","definition":"to make an unhappy or worried face","arabic":"يعبس","example":"Noura frowned when she saw the litter.","image_id":"IMG-RW-L03-U2-LS2-V01","audio_id":"AUD-RW-L03-U2-LS2-V01","tier":"core"},{"word":"plastic","pos":"adjective / noun","ipa":"/ˈplæstɪk/","definition":"a light material used for bottles and bags","arabic":"بلاستيك","example":"Plastic bottles were everywhere.","image_id":"IMG-RW-L03-U2-LS2-V02","audio_id":"AUD-RW-L03-U2-LS2-V02","tier":"core"},{"word":"dust","pos":"noun","ipa":"/dʌst/","definition":"dry dirt like powder","arabic":"غبار","example":"The swings were covered in dust.","image_id":"IMG-RW-L03-U2-LS2-V03","audio_id":"AUD-RW-L03-U2-LS2-V03","tier":"core"},{"word":"sign","pos":"noun","ipa":"/saɪn/","definition":"a board or paper with words that give information","arabic":"لافتة / إعلان","example":"Noura put a sign on the gate.","image_id":"IMG-RW-L03-U2-LS2-V04","audio_id":"AUD-RW-L03-U2-LS2-V04","tier":"core"},{"word":"cane","pos":"noun","ipa":"/keɪn/","definition":"a stick that helps a person walk","arabic":"عصا المشي","example":"Mrs. Amal walks with a cane.","image_id":"IMG-RW-L03-U2-LS2-V05","audio_id":"AUD-RW-L03-U2-LS2-V05","tier":"core"},{"word":"sweep","pos":"verb","ipa":"/swip/","definition":"to clean the floor with a broom (past: swept)","arabic":"يكنس","example":"They swept the paths.","image_id":"IMG-RW-L03-U2-LS2-V06","audio_id":"AUD-RW-L03-U2-LS2-V06","tier":"core"},{"word":"proud","pos":"adjective","ipa":"/praʊd/","definition":"happy about something good you did","arabic":"فخور","example":"Noura felt proud of her team.","image_id":"IMG-RW-L03-U2-LS2-V07","audio_id":"AUD-RW-L03-U2-LS2-V07","tier":"core"}],"explanation":{"text":"In a story, **events** happen in order. Often, **one character's action causes the next event**. This is a **cause → effect chain**.\n\nAsk: **What did the character do? What happened because of it?** Use **because**, **so** and **after that** to explain.\n\nGood readers also ask **why** a character acts: what do they **want** or **feel**? This is the character's **motivation**.","examples":["Cause: **Noura saw the dirty park.** → Effect: **She made a plan.**","Cause: **Noura put a sign on the gate.** → Effect: **Many neighbors came on Saturday.**","Cause: **Faris saw everyone working.** → Effect: **He put on his gloves and ran outside.**","Cause: **The volunteers worked hard.** → Effect: **By noon, the park was clean and bright.**","Motivation: **Noura wanted the park to look happy again.** (\"Our park looks sad.\")","Motivation: **Mrs. Amal brought juice because she wanted to thank and help the children.**","Feeling at the end: **Noura felt proud.**","Explain with *so*: **The park was dirty, so Noura made a clean-up plan.**","Explain with *because*: **Faris helped because he saw that his sister was right.**"],"common_errors":["✗ Retelling every small detail. → ✓ Retell the **main events** that cause the next ones. (Choose events that move the story.)","✗ Noura make a plan. → ✓ Noura made a plan. (The story is in the **past**: made.)","✗ Faris come outside. → ✓ Faris came outside. (Past of come = **came**.)","✗ They sweeped the paths. → ✓ They swept the paths. (Past of sweep = **swept**.)","✗ Mrs. Amal brought juice so she is old. → ✓ Mrs. Amal brought juice because she wanted to help. (Check that the cause really leads to the effect.)","✗ The park was clean. Because the volunteers worked hard. → ✓ The park was clean because the volunteers worked hard. (Don't start a separate sentence with **Because**.)"],"arabic":"في القصة تقع الأحداث بالترتيب، وكثيرًا ما يكون فعل شخصية سببًا في الحدث التالي؛ وهذه سلسلة السبب والنتيجة.\n\nاسأل: ماذا فعلت الشخصية؟ وماذا حدث بسبب ذلك؟ واستخدم because وso وafter that للشرح.\n\nالقارئ الجيد يسأل أيضًا: لماذا تصرفت الشخصية هكذا؟ ماذا تريد أو تشعر؟ وهذا هو دافعها.\n\nالقصة مكتوبة بالماضي: made, came, swept, brought."},"video":{"script":[{"time":"00:00–00:20","narration":"One small action can start a big change. Watch Noura!","on_screen":"Action → Event","visual":"A single domino falls and starts a long chain."},{"time":"00:20–01:40","narration":"Every afternoon, Noura walked past the small park near her house…","on_screen":"(story, part by part)","visual":"Animated story: the dusty park, the colorful sign, Faris laughing, neighbors arriving, Mrs. Amal with juice, Faris joining, the clean park at noon."},{"time":"01:40–02:20","narration":"Noura put a sign on the gate. So what happened? Many neighbors came!","on_screen":"Cause → Effect chain","visual":"Story pictures become dominoes knocking each other over."},{"time":"02:20–02:45","narration":"Why did Noura do it? She wanted her park to be happy again.","on_screen":"Motivation 💭","visual":"A thought bubble over Noura shows a clean, happy park."},{"time":"02:45–03:00","narration":"What action will YOU take to help your community?","on_screen":"Your action!","visual":"Saqr picks up a bottle and drops it in a bin."}],"captions_ar":["فعلٌ صغير يمكن أن يبدأ تغييرًا كبيرًا. شاهد نورة!","كل عصر كانت نورة تمر بالحديقة الصغيرة قرب منزلها…","وضعت نورة لافتة على البوابة، فماذا حدث؟ جاء كثير من الجيران!","لماذا فعلت نورة ذلك؟ أرادت أن تعود حديقتها سعيدة.","ما الفعل الذي ستقوم به أنت لمساعدة مجتمعك؟"],"voice":"Narrator: American English, warm female teacher, speed 0.90. Noura: determined. Faris: doubtful, then eager. Mrs. Amal: gentle elderly voice."},"texts":[{"type":"reading","title":"The Saturday Clean-Up","body":"Every afternoon, Noura walked past the small park near her house. One day, she stopped and frowned. Plastic bottles and bags were everywhere, and the swings were covered in dust. \"Our park looks sad,\" she said.\n\nThat night, Noura made a plan. She wrote a colorful sign: \"Saturday Clean-Up! 9 o'clock. Bring gloves. Everyone is welcome!\" She put it on the park gate.\n\nHer brother Faris laughed. \"Nobody will come. People are too busy.\"\n\nBut on Saturday morning, Noura was not alone. Sami and Lama came with a big bag. Omar brought his whole football team. Even Mrs. Amal, the elderly neighbor who lives next door, came slowly with her cane and a box of cold juice for everyone.\n\nThe volunteers worked hard. They collected bottles, swept the paths and painted the old bench. Faris watched from his window. Then he put on his gloves and ran outside. \"Can I help too?\" he asked. Noura smiled and gave him a bag.\n\nBy noon, the park was clean and bright. Mrs. Amal sat on the bench. \"Thank you, children,\" she said. \"You have made our neighborhood beautiful.\" Noura felt proud. One small idea had become a big team.","word_count":197,"audio_id":"AUD-RW-L03-U2-LS2-T1","id":"TXT-RW-L03-U2-LS2-1","genre":"narrative","role":"main","difficulty":"350L–500L","glossary":[{"word":"frowned","definition":"made an unhappy face","arabic":"عبس / قطّب"},{"word":"cane","definition":"a stick that helps a person walk","arabic":"عصا المشي"},{"word":"swept","definition":"cleaned with a broom (past of sweep)","arabic":"كنس"}]}],"activities":[{"id":"RW-L03-U2-LS2-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Read the story. Choose the answer.","instructions_ar":"اقرأ القصة واختر الإجابة.","items":[{"q":"What did Noura see in the park?","answer":"plastic bottles and bags everywhere","explanation":"Paragraph 1.","explanation_ar":"زجاجات وأكياس بلاستيكية.","options":["a new swing","a big football game","a charity van","plastic bottles and bags everywhere"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"Where did Noura put her sign?","answer":"on the park gate","explanation":"Paragraph 2.","explanation_ar":"على بوابة الحديقة.","options":["on her bedroom door","on the park gate","at school","on the bench"],"dok":1,"skill":"key details: where","stage":"controlled"},{"q":"What did the sign tell people to bring?","answer":"gloves","explanation":"Sign: Bring gloves.","explanation_ar":"قفازات.","options":["juice","brooms only","money","gloves"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"Who brought a whole football team?","answer":"Omar","explanation":"Paragraph 4.","explanation_ar":"عمر.","options":["Sami","Faris","Omar","Lama"],"dok":1,"skill":"characters","stage":"controlled"},{"q":"What did Mrs. Amal bring?","answer":"a box of cold juice","explanation":"Paragraph 4.","explanation_ar":"صندوق عصير بارد.","options":["a box of cold juice","a broom","a new bench","plastic bags"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"What did the volunteers paint?","answer":"the old bench","explanation":"Paragraph 5.","explanation_ar":"المقعد القديم.","options":["the swings","the gate","the old bench","the mosque"],"dok":1,"skill":"key details","stage":"controlled"}]},{"id":"RW-L03-U2-LS2-A2","type":"mcq","stage":"guided","instructions":"Guided practice: Cause and effect. Choose.","instructions_ar":"السبب والنتيجة: اختر.","items":[{"q":"What did Noura do BECAUSE the park looked sad?","answer":"She made a clean-up plan.","explanation":"Cause: sad park → effect: plan.","explanation_ar":"وضعت خطة.","options":["She made a clean-up plan.","She went home to sleep.","She played on the swings.","She laughed at Faris."],"dok":1,"skill":"cause and effect","stage":"guided"},{"q":"What happened BECAUSE Noura put up a sign?","answer":"Many neighbors came on Saturday.","explanation":"The sign invited people.","explanation_ar":"جاء كثير من الجيران.","options":["Faris laughed.","The swings broke.","Many neighbors came on Saturday.","It rained."],"dok":2,"skill":"cause and effect","stage":"guided"},{"q":"Why did Faris put on his gloves and run outside?","answer":"He saw everyone working and wanted to help.","explanation":"He watched from his window first.","explanation_ar":"رأى الجميع يعملون.","options":["Noura shouted at him.","He was cold.","Mrs. Amal called him.","He saw everyone working and wanted to help."],"dok":2,"skill":"motivation","stage":"guided"},{"q":"What was the EFFECT of the volunteers' hard work?","answer":"By noon, the park was clean and bright.","explanation":"Hard work → clean park.","explanation_ar":"صارت الحديقة نظيفة.","options":["Faris laughed.","By noon, the park was clean and bright.","Noura wrote a sign.","Mrs. Amal came with a cane."],"dok":1,"skill":"cause and effect","stage":"guided"},{"q":"Why did Noura make the clean-up?","answer":"She wanted the park to look happy again.","explanation":"\"Our park looks sad.\"","explanation_ar":"أرادت أن تعود الحديقة سعيدة.","options":["She wanted a prize.","Her teacher told her to.","She wanted the park to look happy again.","She wanted to paint."],"dok":2,"skill":"motivation","stage":"guided"},{"q":"How did Faris's feelings change?","answer":"from doubtful to eager to help","explanation":"He laughed, then asked to help.","explanation_ar":"من الشك إلى الحماس.","options":["from happy to angry","from helpful to lazy","They did not change.","from doubtful to eager to help"],"dok":2,"skill":"character change","stage":"guided"}]},{"id":"RW-L03-U2-LS2-A3","type":"highlight","stage":"freer","instructions":"Find the evidence: Find the evidence.","instructions_ar":"ابحث عن الدليل.","items":[{"q":"Underline the sentence that shows Faris did not believe in the plan.","answer":"\"Nobody will come. People are too busy.\"","explanation":"Faris thinks nobody will come.","explanation_ar":"فارس لا يصدّق.","evidence":"\"Nobody will come. People are too busy.\"","text_id":"TXT-RW-L03-U2-LS2-1","dok":1,"skill":"evidence","stage":"freer","sentences":["Every afternoon, Noura walked past the small park near her house.","One day, she stopped and frowned.","Plastic bottles and bags were everywhere, and the swings were covered in dust.","\"Our park looks sad,\" she said.","That night, Noura made a plan.","She wrote a colorful sign: \"Saturday Clean-Up!","9 o'clock.","Bring gloves.","Everyone is welcome!\"","She put it on the park gate.","Her brother Faris laughed.","\"Nobody will come.","People are too busy.\"","But on Saturday morning, Noura was not alone.","Sami and Lama came with a big bag.","Omar brought his whole football team.","Even Mrs.","Amal, the elderly neighbor who lives next door, came slowly with her cane and a box of cold juice for everyone.","The volunteers worked hard.","They collected bottles, swept the paths and painted the old bench.","Faris watched from his window.","Then he put on his gloves and ran outside.","\"Can I help too?\" he asked.","Noura smiled and gave him a bag.","By noon, the park was clean and bright.","Mrs.","Amal sat on the bench.","\"Thank you, children,\" she said.","\"You have made our neighborhood beautiful.\"","Noura felt proud.","One small idea had become a big team."]},{"q":"Underline the words that show Mrs. Amal was grateful.","answer":"\"Thank you, children,\" she said. \"You have made our neighborhood beautiful.\"","explanation":"She thanks them.","explanation_ar":"تشكرهم.","evidence":"\"Thank you, children,\" she said. \"You have made our neighborhood beautiful.\"","text_id":"TXT-RW-L03-U2-LS2-1","dok":2,"skill":"evidence","stage":"freer","sentences":["Every afternoon, Noura walked past the small park near her house.","One day, she stopped and frowned.","Plastic bottles and bags were everywhere, and the swings were covered in dust.","\"Our park looks sad,\" she said.","That night, Noura made a plan.","She wrote a colorful sign: \"Saturday Clean-Up!","9 o'clock.","Bring gloves.","Everyone is welcome!\"","She put it on the park gate.","Her brother Faris laughed.","\"Nobody will come.","People are too busy.\"","But on Saturday morning, Noura was not alone.","Sami and Lama came with a big bag.","Omar brought his whole football team.","Even Mrs.","Amal, the elderly neighbor who lives next door, came slowly with her cane and a box of cold juice for everyone.","The volunteers worked hard.","They collected bottles, swept the paths and painted the old bench.","Faris watched from his window.","Then he put on his gloves and ran outside.","\"Can I help too?\" he asked.","Noura smiled and gave him a bag.","By noon, the park was clean and bright.","Mrs.","Amal sat on the bench.","\"Thank you, children,\" she said.","\"You have made our neighborhood beautiful.\"","Noura felt proud.","One small idea had become a big team."]},{"q":"What does *One small idea had become a big team* mean?","answer":"Noura's plan brought many people together.","explanation":"A small start led to many helpers.","explanation_ar":"خطة صغيرة جمعت كثيرين.","options":["Noura's plan brought many people together.","Noura's idea was very small.","The team was too big for the park.","Noura stopped the idea."],"dok":3,"skill":"figurative meaning","stage":"freer"},{"q":"Why did the writer include Mrs. Amal coming *slowly with her cane*?","answer":"to show that even an elderly neighbor wanted to help","explanation":"Even someone who walks slowly came.","explanation_ar":"ليُظهر أن حتى المسنّة أرادت المساعدة.","options":["to show she was late","to show that even an elderly neighbor wanted to help","to show she was angry","to explain how to use a cane"],"dok":3,"skill":"author's craft","stage":"freer"}]},{"id":"RW-L03-U2-LS2-A4","type":"open","stage":"production","instructions":"Writing: Explain and evaluate.","instructions_ar":"اشرح وقيّم.","items":[{"q":"Write a cause → effect sentence about the story with *so*.","answer":"Noura put a sign on the gate, so many neighbors came.","explanation":"Cause, so effect.","explanation_ar":"سبب، so نتيجة.","dok":2,"skill":"cause and effect","stage":"production"},{"q":"Write a sentence about Faris with *because*.","answer":"Faris went outside because he saw everyone working together.","explanation":"Effect because cause.","explanation_ar":"نتيجة because سبب.","dok":2,"skill":"cause and effect","stage":"production"},{"q":"Was Faris right when he said *Nobody will come*? Use evidence.","answer":"No. The story says Sami, Lama, Omar's team and Mrs. Amal came.","explanation":"Evaluate + evidence.","explanation_ar":"تقييم + دليل.","dok":3,"skill":"evaluate","stage":"production"},{"q":"What lesson does the story teach? Explain.","answer":"One person can start a big change when others join to help.","explanation":"Lesson + explanation.","explanation_ar":"الدرس + الشرح.","dok":3,"skill":"theme","stage":"production"}]},{"id":"RW-L03-U2-LS2-TR-1","type":"timed_reading","instructions":"Timed reading: Read \"The Saturday Clean-Up\" aloud or silently. Try to finish in the time.","instructions_ar":"اقرأ النص وحاول أن تنهيه في الوقت المحدد.","items":[{"q":"Read “The Saturday Clean-Up”.","answer":"197 words","title":"The Saturday Clean-Up","body":"Every afternoon, Noura walked past the small park near her house. One day, she stopped and frowned. Plastic bottles and bags were everywhere, and the swings were covered in dust. \"Our park looks sad,\" she said.\n\nThat night, Noura made a plan. She wrote a colorful sign: \"Saturday Clean-Up! 9 o'clock. Bring gloves. Everyone is welcome!\" She put it on the park gate.\n\nHer brother Faris laughed. \"Nobody will come. People are too busy.\"\n\nBut on Saturday morning, Noura was not alone. Sami and Lama came with a big bag. Omar brought his whole football team. Even Mrs. Amal, the elderly neighbor who lives next door, came slowly with her cane and a box of cold juice for everyone.\n\nThe volunteers worked hard. They collected bottles, swept the paths and painted the old bench. Faris watched from his window. Then he put on his gloves and ran outside. \"Can I help too?\" he asked. Noura smiled and gave him a bag.\n\nBy noon, the park was clean and bright. Mrs. Amal sat on the bench. \"Thank you, children,\" she said. \"You have made our neighborhood beautiful.\" Noura felt proud. One small idea had become a big team.","words":197,"limit":183}],"time_limit_sec":183}],"game":{"name":"Domino Story","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Story dominoes: event cards are mixed on screen; the child drags them into a chain. When the order is right, the dominoes fall one by one and the narrator reads each link with 'so'.","Teams get eight domino event cards.","They line them up in story order.","A player reads the chain aloud, joining each pair with 'so'.","Other teams listen and check the order with the story.","Correct chain = 3 points; fastest correct chain = bonus point."],"data":[]},"exit_quiz":[{"q":"Who had the idea for the clean-up?","answer":"Noura","explanation":"Noura made the plan.","explanation_ar":"نورة.","options":["Faris","Noura","Mrs. Amal","Omar"],"dok":1,"skill":"characters"},{"q":"Where does Mrs. Amal live?","answer":"next door to Noura","explanation":"the elderly neighbor who lives next door","explanation_ar":"بجوار نورة.","options":["at the school","far away in another city","in the park","next door to Noura"],"dok":1,"skill":"key details"},{"q":"*She stopped and frowned.* *Frowned* means ___.","answer":"made an unhappy face","explanation":"Frown = unhappy face.","explanation_ar":"عبست.","options":["laughed loudly","ran away","sang a song","made an unhappy face"],"dok":1,"skill":"vocabulary in context"},{"q":"Which event came FIRST?","answer":"Noura saw the dirty park.","explanation":"The story begins with the dirty park.","explanation_ar":"رأت نورة الحديقة المتسخة.","options":["Noura saw the dirty park.","Faris put on his gloves.","Mrs. Amal sat on the bench.","The volunteers painted the bench."],"dok":1,"skill":"sequence"},{"q":"What caused Faris to change his mind?","answer":"seeing everyone working in the park","explanation":"He watched from his window.","explanation_ar":"رأى الجميع يعملون.","options":["a phone call","seeing everyone working in the park","the rain","a sign at school"],"dok":2,"skill":"cause and effect"},{"q":"Which sentence uses the past tense correctly?","answer":"They swept the paths and painted the bench.","explanation":"Past: swept, painted.","explanation_ar":"الماضي الصحيح.","options":["They swept the paths and painted the bench.","They sweeped the paths and paint the bench.","They sweep the paths and painted the bench.","They swepted the paths."],"dok":2,"skill":"grammar"},{"q":"How did Noura feel at the end?","answer":"proud","explanation":"Text: Noura felt proud.","explanation_ar":"فخورة.","options":["angry","bored","proud","scared"],"dok":1,"skill":"character feelings"},{"q":"Which word BEST describes Noura in this story?","answer":"responsible","explanation":"She made a plan and led the team.","explanation_ar":"مسؤولة.","options":["lazy","selfish","careless","responsible"],"dok":2,"skill":"character traits"},{"q":"Why did the writer end with *One small idea had become a big team*?","answer":"to show the big result of Noura's small action","explanation":"It sums up the change.","explanation_ar":"ليُظهر النتيجة الكبيرة لفعل صغير.","options":["to start a new story","to introduce a new character","to show the big result of Noura's small action","to describe the weather"],"dok":3,"skill":"author's craft"},{"q":"Which is the best lesson of *The Saturday Clean-Up*?","answer":"When people work together, they can make big changes.","explanation":"The team changed the park.","explanation_ar":"العمل الجماعي يصنع تغييرًا كبيرًا.","options":["Parks are always dirty.","Brothers are always right.","When people work together, they can make big changes.","Juice is the best drink."],"dok":3,"skill":"theme"}],"images":[{"id":"IMG-RW-L03-U2-LS2-V01","prompt":"Picture for the word 'frown': a girl frowning at a messy park"},{"id":"IMG-RW-L03-U2-LS2-V02","prompt":"Picture for the word 'plastic': a pile of plastic bottles"},{"id":"IMG-RW-L03-U2-LS2-V03","prompt":"Picture for the word 'dust': a dusty swing"},{"id":"IMG-RW-L03-U2-LS2-V04","prompt":"Picture for the word 'sign': a colorful paper sign on a gate"},{"id":"IMG-RW-L03-U2-LS2-V05","prompt":"Picture for the word 'cane': a wooden walking cane"},{"id":"IMG-RW-L03-U2-LS2-V06","prompt":"Picture for the word 'sweep': a child sweeping a path"},{"id":"IMG-RW-L03-U2-LS2-V07","prompt":"Picture for the word 'proud': a girl smiling with hands on her hips"},{"id":"IMG-RW-L03-U2-LS2-01","prompt":"Noura frowns at a dirty, dusty park."},{"id":"IMG-RW-L03-U2-LS2-02","prompt":"Neighbors clean the park while Mrs. Amal gives out juice and Faris runs to help."},{"id":"IMG-RW-L03-U2-LS2-03","prompt":"Mrs. Amal sits on the new bench in the clean park."}],"audio":[{"id":"AUD-RW-L03-U2-LS2-V01","script":"frown. Noura frowned when she saw the litter."},{"id":"AUD-RW-L03-U2-LS2-V02","script":"plastic. Plastic bottles were everywhere."},{"id":"AUD-RW-L03-U2-LS2-V03","script":"dust. The swings were covered in dust."},{"id":"AUD-RW-L03-U2-LS2-V04","script":"sign. Noura put a sign on the gate."},{"id":"AUD-RW-L03-U2-LS2-V05","script":"cane. Mrs. Amal walks with a cane."},{"id":"AUD-RW-L03-U2-LS2-V06","script":"sweep. They swept the paths."},{"id":"AUD-RW-L03-U2-LS2-V07","script":"proud. Noura felt proud of her team."},{"id":"AUD-RW-L03-U2-LS2-T1","script":"Every afternoon, Noura walked past the small park near her house. One day, she stopped and frowned. Plastic bottles and bags were everywhere, and the swings were covered in dust. \"Our park looks sad,\" she said. That night, Noura made a plan. She wrote a colorful sign: \"Saturday Clean-Up! 9 o'clock. Bring gloves. Everyone is welcome!\" She put it on the park gate. Her brother Faris laughed. \"Nobody will come. People are too busy.\" But on Saturday morning, Noura was not alone. Sami and Lama came with a big bag. Omar brought his whole football team. Even Mrs. Amal, the elderly neighbor who lives next door, came slowly with her cane and a box of cold juice for everyone. The volunteers worked hard. They collected bottles, swept the paths and painted the old bench. Faris watched from his window. Then he put on his gloves and ran outside. \"Can I help too?\" he asked. Noura smiled and gave him a bag. By noon, the park was clean and bright. Mrs. Amal sat on the bench. \"Thank you, children,\" she said. \"You have made our neighborhood beautiful.\" Noura felt proud. One small idea had become a big team."},{"id":"AUD-RW-L03-U2-LS2-VID","script":"One small action can start a big change. Watch Noura! Every afternoon, Noura walked past the small park near her house… Noura put a sign on the gate. So what happened? Many neighbors came! Why did Noura do it? She wanted her park to be happy again. What action will YOU take to help your community?"}]},{"id":"RW-L03-U2-LS3","title":"Character traits with evidence: \"Dear Mrs. Amal\"","lesson_type":"strategy_paired_text","objectives":["describe a character's traits using what the character says, does and feels","support each trait with evidence from the text","complete a Character Web for Mrs. Amal using the story and the letter"],"objectives_ar":["وصف صفات الشخصية مما تقوله وتفعله وتشعر به.","دعم كل صفة بدليل من النص.","إكمال شبكة الشخصية للسيدة آمال باستخدام القصة والرسالة."],"success_criteria":["I can tell the difference between a trait and a feeling.","I can name a trait and give evidence for it.","I can use two texts to describe one character."],"success_criteria_ar":["أستطيع التمييز بين الصفة والشعور.","أستطيع تسمية صفة وتقديم دليل عليها.","أستطيع استخدام نصين لوصف شخصية واحدة."],"map_area":"Informational Text: Key Ideas and Details","vocabulary":[{"word":"letter","pos":"noun","ipa":"/ˈlɛtər/","definition":"a written message to someone","arabic":"رسالة","example":"Noura wrote a letter to Mrs. Amal.","image_id":"IMG-RW-L03-U2-LS3-V01","audio_id":"AUD-RW-L03-U2-LS3-V01","tier":"core"},{"word":"special","pos":"adjective","ipa":"/ˈspɛʃəl/","definition":"important, different and loved","arabic":"مميّز","example":"The park is special to Mrs. Amal.","image_id":"IMG-RW-L03-U2-LS3-V02","audio_id":"AUD-RW-L03-U2-LS3-V02","tier":"core"},{"word":"shopping","pos":"noun","ipa":"/ˈʃɑpɪŋ/","definition":"the things you buy at the shops","arabic":"المشتريات","example":"We can carry your shopping.","image_id":"IMG-RW-L03-U2-LS3-V03","audio_id":"AUD-RW-L03-U2-LS3-V03","tier":"core"},{"word":"feeling","pos":"noun","ipa":"/ˈfilɪŋ/","definition":"how someone feels for a short time (happy, sad, proud)","arabic":"شعور","example":"Proud is a feeling.","image_id":"IMG-RW-L03-U2-LS3-V04","audio_id":"AUD-RW-L03-U2-LS3-V04","tier":"core"},{"word":"kind","pos":"adjective","ipa":"/kaɪnd/","definition":"nice and caring to others","arabic":"لطيف","example":"That was very kind of you.","image_id":"IMG-RW-L03-U2-LS3-V05","audio_id":"AUD-RW-L03-U2-LS3-V05","tier":"core"},{"word":"thoughtful","pos":"adjective","ipa":"/ˈθɔtfəl/","definition":"thinking about what other people need","arabic":"مراعٍ لمشاعر الآخرين","example":"The thoughtful team offered to visit every week.","image_id":"IMG-RW-L03-U2-LS3-V06","audio_id":"AUD-RW-L03-U2-LS3-V06","tier":"core"},{"word":"determined","pos":"adjective","ipa":"/dɪˈtɝmɪnd/","definition":"not giving up, even when it is hard","arabic":"مصمّم / عازم","example":"Noura was determined to clean the park.","image_id":"IMG-RW-L03-U2-LS3-V07","audio_id":"AUD-RW-L03-U2-LS3-V07","tier":"core"}],"explanation":{"text":"A **trait** tells what a character is like **inside**, most of the time: *kind, generous, determined, lazy*. A **feeling** changes quickly: *happy, sad, proud, angry*.\n\nWe find traits by looking at what a character **says**, **does** and **thinks**, and what **other characters say** about them.\n\nAlways give **evidence**: *Mrs. Amal is **generous**. **Evidence:** she brought a box of cold juice for everyone.* Use **because** to connect the trait and the evidence.","examples":["Noura – **determined**: she made a plan and a sign even when Faris laughed.","Noura – **responsible**: she put the sign on the gate and gave Faris a bag to work.","Faris – **doubtful** at first: \"Nobody will come.\" → later **helpful**: \"Can I help too?\"","Mrs. Amal – **generous**: she brought cold juice for everyone (story).","Mrs. Amal – **kind and caring**: she walked with her cane to help (story + letter).","Mrs. Amal – **wise**: she shared a story about the park when it was new (letter).","Noura and the team – **grateful**: they wrote a thank-you letter (letter).","Noura and the team – **thoughtful**: they offered to water her plants and carry her shopping (letter).","Trait vs. feeling: Noura felt **proud** (feeling) because she is **determined** (trait)."],"common_errors":["✗ Mrs. Amal is happy. (as a trait) → ✓ Mrs. Amal is generous. (trait) (Happy is usually a **feeling**; use a trait word.)","✗ Noura is nice. → ✓ Noura is determined because she made a plan even when Faris laughed. (Use a **precise** trait and **evidence**.)","✗ Mrs. Amal is generous. (no evidence) → ✓ Mrs. Amal is generous because she brought juice for everyone. (Always add **evidence**.)","✗ Faris is lazy. (only the beginning) → ✓ Faris doubted the plan at first, but later he was helpful. (Look at the **whole** story.)","✗ The letter thanks Mrs. Amal for help us. → ✓ The letter thanks Mrs. Amal for helping us. (for + **-ing**.)","✗ Mrs. Amal walk with a cane. → ✓ Mrs. Amal walks with a cane. (One person → **walks**.)"],"arabic":"الصفة (trait) تخبر عن الشخصية من الداخل في معظم الوقت: لطيفة، كريمة، مصمّمة. أما الشعور (feeling) فيتغير بسرعة: سعيدة، حزينة، فخورة.\n\nنعرف الصفات مما تقوله الشخصية وتفعله وتفكر فيه، ومما يقوله الآخرون عنها.\n\nقدّم الدليل دائمًا واربطه بالصفة بكلمة because: Mrs. Amal is generous because she brought juice for everyone.\n\nيمكن استخدام نصين (القصة والرسالة) لوصف الشخصية نفسها بصورة أكمل."},"video":{"script":[{"time":"00:00–00:20","narration":"What is Mrs. Amal really like? Let's be character detectives!","on_screen":"Character Traits 🕵️","visual":"A magnifying glass over a picture of Mrs. Amal."},{"time":"00:20–00:55","narration":"A trait is what someone is like inside. A feeling changes quickly.","on_screen":"Trait 🧡 vs. Feeling 🙂","visual":"Two boxes: 'generous, kind' stays; 'happy, tired' bubbles pop and change."},{"time":"00:55–01:55","narration":"Dear Mrs. Amal, Thank you for helping us with the Saturday Clean-Up!…","on_screen":"(letter)","visual":"The letter appears on paper with a pressed flower; scenes from the story flash beside each part."},{"time":"01:55–02:35","narration":"Mrs. Amal is generous. Evidence: she brought cold juice for everyone!","on_screen":"Trait + because + evidence","visual":"A Character Web fills: trait bubbles connect to evidence notes."},{"time":"02:35–03:00","narration":"And the writers? They are grateful and thoughtful – look at what they offer!","on_screen":"Writers' traits too!","visual":"Children water plants and carry shopping for Mrs. Amal."}],"captions_ar":["كيف هي السيدة آمال حقًا؟ لنكن محققي الشخصيات!","الصفة هي ما يكون عليه الشخص من الداخل، والشعور يتغير بسرعة.","عزيزتي السيدة آمال، شكرًا لمساعدتنا في حملة تنظيف السبت!","السيدة آمال كريمة. الدليل: أحضرت عصيرًا باردًا للجميع!","والكُتّاب؟ ممتنون ومراعون للآخرين؛ انظر إلى ما يعرضونه!"],"voice":"Narrator: American English, warm female teacher, speed 0.90. Letter reader: Noura's clear, grateful voice."},"texts":[{"type":"reading","title":"Dear Mrs. Amal","body":"November 15\n\nDear Mrs. Amal,\n\nThank you for helping us with the Saturday Clean-Up! The cold juice you brought was the best part of the morning. You walked to the park with your cane, but you still came to help us. That was very kind of you.\n\nWe also loved your story about the park when it was new. Now we know why it is so special to you.\n\nThe volunteers want to visit you every Thursday after school. We can water your plants, carry your shopping or just drink tea and listen to more of your stories.\n\nWith love and thanks,\n\nNoura and the Saturday Team","word_count":107,"audio_id":"AUD-RW-L03-U2-LS3-T1","id":"TXT-RW-L03-U2-LS3-1","genre":"letter/email","role":"paired","difficulty":"350L–500L","glossary":[{"word":"special","definition":"important and loved","arabic":"مميّز / عزيز"},{"word":"shopping","definition":"the things you buy at the shops","arabic":"المشتريات"},{"word":"with love and thanks","definition":"a warm way to end a letter","arabic":"مع الحب والشكر"}]}],"activities":[{"id":"RW-L03-U2-LS3-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Read *Dear Mrs. Amal*. Choose the answer.","instructions_ar":"اقرأ الرسالة واختر الإجابة.","items":[{"q":"Who wrote the letter *Dear Mrs. Amal*?","answer":"Noura and the Saturday Team","explanation":"The signature.","explanation_ar":"نورة وفريق السبت.","options":["Mrs. Amal","Noura and the Saturday Team","Faris","Mr. Khalid"],"dok":1,"skill":"letter parts","text_id":"TXT-RW-L03-U2-LS3-1","stage":"controlled"},{"q":"Why did they write the letter?","answer":"to thank Mrs. Amal and offer help","explanation":"Thank you… We can…","explanation_ar":"للشكر وعرض المساعدة.","options":["to invite her to a party","to thank Mrs. Amal and offer help","to ask for money","to say sorry"],"dok":1,"skill":"purpose","stage":"controlled"},{"q":"What was *the best part of the morning*?","answer":"the cold juice","explanation":"Letter paragraph 1.","explanation_ar":"العصير البارد.","options":["the cold juice","painting the bench","the rain","Faris's joke"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"What did Mrs. Amal tell the children about?","answer":"the park when it was new","explanation":"Letter paragraph 2.","explanation_ar":"الحديقة حين كانت جديدة.","options":["the park when it was new","her trip to Canada","how to make juice","her cat"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"When do the volunteers want to visit Mrs. Amal?","answer":"every Thursday after school","explanation":"Letter paragraph 3.","explanation_ar":"كل خميس بعد المدرسة.","options":["every Saturday morning","once a year","every night","every Thursday after school"],"dok":1,"skill":"key details: when","stage":"controlled"},{"q":"Which is NOT something the team offers to do?","answer":"paint her house","explanation":"Painting is not in the letter.","explanation_ar":"طلاء منزلها.","options":["water her plants","carry her shopping","paint her house","listen to her stories"],"dok":2,"skill":"key details","stage":"controlled"}]},{"id":"RW-L03-U2-LS3-A2","type":"mcq","stage":"guided","instructions":"Guided practice: Traits and evidence. Choose.","instructions_ar":"الصفات والأدلة: اختر.","items":[{"q":"Which word is a TRAIT, not a feeling?","answer":"generous","explanation":"Generous is what someone is like inside.","explanation_ar":"generous صفة.","options":["tired","generous","hungry","surprised"],"dok":1,"skill":"trait vs. feeling","stage":"guided"},{"q":"Which evidence shows that Mrs. Amal is generous?","answer":"She brought a box of cold juice for everyone.","explanation":"Giving juice = generous.","explanation_ar":"أحضرت العصير.","options":["She walked slowly.","She brought a box of cold juice for everyone.","She lives next door.","She sat on the bench."],"dok":2,"skill":"evidence","stage":"guided"},{"q":"Which trait fits Mrs. Amal because she *walked to the park with her cane, but still came to help*?","answer":"kind and caring","explanation":"She helped even though it was hard.","explanation_ar":"لطيفة ومهتمة.","options":["kind and caring","lazy","careless","selfish"],"dok":2,"skill":"character traits","stage":"guided"},{"q":"What trait does the letter show about the WRITERS?","answer":"grateful","explanation":"They say thank you.","explanation_ar":"ممتنون.","options":["careless","angry","greedy","grateful"],"dok":1,"skill":"character traits","stage":"guided"},{"q":"The team offers to water her plants and carry her shopping. This shows they are ___.","answer":"thoughtful","explanation":"They think about what she needs.","explanation_ar":"مراعون.","options":["fearful","useless","thoughtful","bored"],"dok":2,"skill":"character traits","stage":"guided"},{"q":"Which sentence gives a trait AND evidence?","answer":"Noura is determined because she made a plan even when Faris laughed.","explanation":"Trait + because + evidence.","explanation_ar":"صفة + دليل.","options":["Noura is determined because she made a plan even when Faris laughed.","Noura is nice.","Noura wrote a sign.","Noura is a girl."],"dok":2,"skill":"trait + evidence","stage":"guided"}]},{"id":"RW-L03-U2-LS3-A3","type":"organizer","stage":"freer","instructions":"Organizer: Complete the Character Web for Mrs. Amal.","instructions_ar":"أكمل شبكة الشخصية للسيدة آمال.","items":[{"q":"Trait 1 + evidence from the story.","answer":"generous – she brought cold juice for everyone.","explanation":"Trait + evidence.","explanation_ar":"صفة + دليل.","dok":2,"skill":"character traits","stage":"freer"},{"q":"Trait 2 + evidence from the letter.","answer":"wise – she told the children a story about the park when it was new.","explanation":"Trait + evidence.","explanation_ar":"صفة + دليل.","dok":2,"skill":"character traits","stage":"freer"},{"q":"A feeling Mrs. Amal had + evidence.","answer":"grateful – she said, \"Thank you, children.\"","explanation":"Feeling + evidence.","explanation_ar":"شعور + دليل.","dok":2,"skill":"feelings","stage":"freer"},{"q":"An action of Mrs. Amal and what it shows.","answer":"She came with her cane; it shows she really cares about her neighborhood.","explanation":"Action + what it shows.","explanation_ar":"فعل + ما يدل عليه.","dok":3,"skill":"inference","stage":"freer"}]},{"id":"RW-L03-U2-LS3-A4","type":"open","stage":"production","instructions":"Writing: Write about characters.","instructions_ar":"اكتب عن الشخصيات.","items":[{"q":"Write one trait for Faris at the END of the story with evidence.","answer":"Faris is helpful because he put on his gloves and asked, \"Can I help too?\"","explanation":"Trait + because + evidence.","explanation_ar":"صفة + because + دليل.","dok":2,"skill":"character traits","stage":"production"},{"q":"How does the letter help you understand Mrs. Amal better than the story alone?","answer":"The letter tells about her story of the park, so I learn she is wise and loves the park.","explanation":"New information from the letter.","explanation_ar":"معلومة جديدة من الرسالة.","dok":3,"skill":"compare texts","stage":"production"},{"q":"Which trait of Mrs. Amal do you want to have? Why?","answer":"I want to be generous like Mrs. Amal because sharing makes people happy.","explanation":"Trait + reason.","explanation_ar":"صفة + سبب.","dok":3,"skill":"connect","stage":"production"},{"q":"Write a trait for someone in your community with evidence.","answer":"Our imam is patient because he teaches the Quran to young children every day.","explanation":"Trait + evidence.","explanation_ar":"صفة + دليل.","dok":2,"skill":"apply","stage":"production"}]},{"id":"RW-L03-U2-LS3-TR-1","type":"timed_reading","instructions":"Timed reading: Read \"Dear Mrs. Amal\" aloud or silently. Try to finish in the time.","instructions_ar":"اقرأ النص وحاول أن تنهيه في الوقت المحدد.","items":[{"q":"Read “Dear Mrs. Amal”.","answer":"107 words","title":"Dear Mrs. Amal","body":"November 15\n\nDear Mrs. Amal,\n\nThank you for helping us with the Saturday Clean-Up! The cold juice you brought was the best part of the morning. You walked to the park with your cane, but you still came to help us. That was very kind of you.\n\nWe also loved your story about the park when it was new. Now we know why it is so special to you.\n\nThe volunteers want to visit you every Thursday after school. We can water your plants, carry your shopping or just drink tea and listen to more of your stories.\n\nWith love and thanks,\n\nNoura and the Saturday Team","words":107,"limit":106}],"time_limit_sec":106},{"id":"RW-L03-U2-LS3-ORG","type":"organizer","organizer":"Character Web","instructions":"Organizer: Write the character's name in the center. In each bubble, write a trait, a feeling or an action and the evidence for it.","items":[{"q":"Center – character: Mrs. Amal","answer":"Mrs. Amal, the elderly neighbor"},{"q":"Trait 1 + evidence","answer":"generous – she brought cold juice for everyone"},{"q":"Trait 2 + evidence","answer":"wise – she told a story about the park when it was new"},{"q":"A feeling + evidence","answer":"grateful – \"Thank you, children.\""},{"q":"An action + what it shows","answer":"came with her cane – shows she is kind and caring"}]}],"game":{"name":"Trait Detectives","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Trait match: an evidence card appears ('She brought juice for everyone'); the child chooses the character and then the trait. Correct matches add a badge to the character's web.","Teams get a set of character, trait and evidence cards.","They make sets: character + trait + evidence.","Each team reads one set aloud: '___ is ___ because ___.'","Other teams check the evidence in the story or letter.","Correct set = 2 points; a set from the letter = bonus point."],"data":[]},"exit_quiz":[{"q":"A character trait tells ___.","answer":"what a character is like inside","explanation":"Trait = inside quality.","explanation_ar":"ما تكون عليه الشخصية من الداخل.","options":["where the story happens","how a story ends","the date of a letter","what a character is like inside"],"dok":1,"skill":"traits"},{"q":"Which word in this list names a FEELING, not a trait?","answer":"proud","explanation":"Proud changes quickly.","explanation_ar":"proud شعور.","options":["proud","generous","honest","responsible"],"dok":1,"skill":"trait vs. feeling"},{"q":"Where can you find evidence for a trait?","answer":"in what the character says and does","explanation":"Words and actions show traits.","explanation_ar":"في أقوال الشخصية وأفعالها.","options":["only in the title","in the page number","in what the character says and does","in the date of the letter"],"dok":1,"skill":"strategy"},{"q":"*We can carry your shopping.* *Shopping* here means ___.","answer":"the things you buy at the shops","explanation":"Shopping = bought things.","explanation_ar":"المشتريات.","options":["a big shop","a kind of juice","the things you buy at the shops","a walking stick"],"dok":1,"skill":"vocabulary"},{"q":"*Noura was determined.* What does *determined* mean?","answer":"not giving up, even when it is hard","explanation":"Determined = keeps going.","explanation_ar":"مصمّمة.","options":["very sleepy","not giving up, even when it is hard","afraid of everything","very old"],"dok":1,"skill":"vocabulary"},{"q":"Which is the BEST evidence that Mrs. Amal loves the park?","answer":"She told the children a story about the park when it was new.","explanation":"Her story shows it is special to her.","explanation_ar":"قصتها عن الحديقة.","options":["She lives next door.","She has a cane.","She is elderly.","She told the children a story about the park when it was new."],"dok":2,"skill":"evidence"},{"q":"Which sentence describes Faris CORRECTLY for the whole story?","answer":"Faris doubted the plan at first, but later he became helpful.","explanation":"His traits changed.","explanation_ar":"تغيّر فارس.","options":["Faris was helpful from the beginning.","Faris was always lazy.","Faris doubted the plan at first, but later he became helpful.","Faris did not do anything."],"dok":2,"skill":"character change"},{"q":"Which trait word is more PRECISE than *nice*?","answer":"generous","explanation":"Precise words tell more.","explanation_ar":"generous أدق.","options":["generous","good","okay","fine"],"dok":2,"skill":"word choice"},{"q":"How does reading BOTH the story and the letter help you?","answer":"You get more evidence to describe Mrs. Amal.","explanation":"Two texts = more evidence.","explanation_ar":"أدلة أكثر.","options":["You can skip the story.","You get more evidence to describe Mrs. Amal.","You learn the date only.","The letter tells a different ending."],"dok":3,"skill":"compare texts"},{"q":"Why did the team offer to visit Mrs. Amal every week?","answer":"They wanted to thank her and help an elderly neighbor.","explanation":"Gratitude and care.","explanation_ar":"للشكر ومساعدة جارة مسنّة.","options":["They wanted juice every week.","Mr. Khalid told them to.","They wanted to paint her house.","They wanted to thank her and help an elderly neighbor."],"dok":3,"skill":"motivation"}],"images":[{"id":"IMG-RW-L03-U2-LS3-V01","prompt":"Picture for the word 'letter': an envelope and a handwritten letter"},{"id":"IMG-RW-L03-U2-LS3-V02","prompt":"Picture for the word 'special': a heart around a park bench"},{"id":"IMG-RW-L03-U2-LS3-V03","prompt":"Picture for the word 'shopping': a child carrying grocery bags"},{"id":"IMG-RW-L03-U2-LS3-V04","prompt":"Picture for the word 'feeling': faces showing happy, sad and proud"},{"id":"IMG-RW-L03-U2-LS3-V05","prompt":"Picture for the word 'kind': a girl giving a flower to a friend"},{"id":"IMG-RW-L03-U2-LS3-V06","prompt":"Picture for the word 'thoughtful': a child bringing tea to an elderly woman"},{"id":"IMG-RW-L03-U2-LS3-V07","prompt":"Picture for the word 'determined': a girl pushing a heavy wheelbarrow with a smile"},{"id":"IMG-RW-L03-U2-LS3-01","prompt":"Mrs. Amal reads a thank-you letter from the children."},{"id":"IMG-RW-L03-U2-LS3-02","prompt":"A character web organizer."},{"id":"IMG-RW-L03-U2-LS3-03","prompt":"Traits shown as a solid heart and feelings as changing bubbles."}],"audio":[{"id":"AUD-RW-L03-U2-LS3-V01","script":"letter. Noura wrote a letter to Mrs. Amal."},{"id":"AUD-RW-L03-U2-LS3-V02","script":"special. The park is special to Mrs. Amal."},{"id":"AUD-RW-L03-U2-LS3-V03","script":"shopping. We can carry your shopping."},{"id":"AUD-RW-L03-U2-LS3-V04","script":"feeling. Proud is a feeling."},{"id":"AUD-RW-L03-U2-LS3-V05","script":"kind. That was very kind of you."},{"id":"AUD-RW-L03-U2-LS3-V06","script":"thoughtful. The thoughtful team offered to visit every week."},{"id":"AUD-RW-L03-U2-LS3-V07","script":"determined. Noura was determined to clean the park."},{"id":"AUD-RW-L03-U2-LS3-T1","script":"November 15 Dear Mrs. Amal, Thank you for helping us with the Saturday Clean-Up! The cold juice you brought was the best part of the morning. You walked to the park with your cane, but you still came to help us. That was very kind of you. We also loved your story about the park when it was new. Now we know why it is so special to you. The volunteers want to visit you every Thursday after school. We can water your plants, carry your shopping or just drink tea and listen to more of your stories. With love and thanks, Noura and the Saturday Team"},{"id":"AUD-RW-L03-U2-LS3-VID","script":"What is Mrs. Amal really like? Let's be character detectives! A trait is what someone is like inside. A feeling changes quickly. Dear Mrs. Amal, Thank you for helping us with the Saturday Clean-Up!… Mrs. Amal is generous. Evidence: she brought cold juice for everyone! And the writers? They are grateful and thoughtful – look at what they offer!"}]},{"id":"RW-L03-U2-LS4","title":"Writing Skill: Friendly letter format","lesson_type":"writing_skill","objectives":["name and use the five parts of a friendly letter: date, greeting, body, closing, signature","write a body that starts with the purpose and gives details","use capitals and commas correctly in the date, greeting and closing"],"objectives_ar":["تسمية أجزاء الرسالة الودية الخمسة واستخدامها: التاريخ والتحية والمتن والختام والتوقيع.","كتابة متن يبدأ بالغرض ويعطي التفاصيل.","استخدام الحروف الكبيرة والفواصل بشكل صحيح في التاريخ والتحية والختام."],"success_criteria":["I can name the five parts of a friendly letter.","I can write a greeting and a closing with commas.","I can write a body with a purpose and details."],"success_criteria_ar":["أستطيع تسمية أجزاء الرسالة الودية الخمسة.","أستطيع كتابة تحية وختام مع الفواصل.","أستطيع كتابة متن فيه غرض وتفاصيل."],"map_area":"Language Usage: Write, Revise Texts for Purpose and Audience (cross-strand)","vocabulary":[{"word":"greeting","pos":"noun","ipa":"/ˈɡritɪŋ/","definition":"the hello part at the start of a letter (Dear …,)","arabic":"التحية","example":"Start your letter with a greeting.","image_id":"IMG-RW-L03-U2-LS4-V01","audio_id":"AUD-RW-L03-U2-LS4-V01","tier":"core"},{"word":"body","pos":"noun","ipa":"/ˈbɑdi/","definition":"the main part of a letter with the message","arabic":"متن الرسالة","example":"The body tells the reader your message.","image_id":"IMG-RW-L03-U2-LS4-V02","audio_id":"AUD-RW-L03-U2-LS4-V02","tier":"core"},{"word":"closing","pos":"noun","ipa":"/ˈkloʊzɪŋ/","definition":"the goodbye words at the end of a letter (Your friend,)","arabic":"الخاتمة (عبارة الختام)","example":"My closing is 'Your cousin,'.","image_id":"IMG-RW-L03-U2-LS4-V03","audio_id":"AUD-RW-L03-U2-LS4-V03","tier":"core"},{"word":"signature","pos":"noun","ipa":"/ˈsɪɡnətʃər/","definition":"your name written at the end of a letter","arabic":"التوقيع","example":"Write your signature under the closing.","image_id":"IMG-RW-L03-U2-LS4-V04","audio_id":"AUD-RW-L03-U2-LS4-V04","tier":"core"},{"word":"invite","pos":"verb","ipa":"/ɪnˈvaɪt/","definition":"to ask someone to come to something","arabic":"يدعو","example":"I invite you to our school event.","image_id":"IMG-RW-L03-U2-LS4-V05","audio_id":"AUD-RW-L03-U2-LS4-V05","tier":"core"},{"word":"purpose","pos":"noun","ipa":"/ˈpɝpəs/","definition":"the reason you do or write something","arabic":"الغرض / الهدف","example":"The purpose of my letter is to say thank you.","image_id":"IMG-RW-L03-U2-LS4-V06","audio_id":"AUD-RW-L03-U2-LS4-V06","tier":"core"},{"word":"reply","pos":"verb / noun","ipa":"/rɪˈplaɪ/","definition":"to answer a letter or message","arabic":"يرد / رد","example":"Please reply soon.","image_id":"IMG-RW-L03-U2-LS4-V07","audio_id":"AUD-RW-L03-U2-LS4-V07","tier":"core"}],"explanation":{"text":"A **friendly letter** is a letter to someone you know: a friend, a relative or a neighbor. It has **five parts** in this order: **date → greeting → body → closing → signature**.\n\nThe **body** starts with the **purpose** (why you are writing: to thank, to invite, to offer help). Then it gives **details** (what, when, where, why). End the body with a friendly sentence (*Please write back soon.*).\n\nPunctuation: a **comma after the greeting** (*Dear Hamza,*) and **after the closing** (*Your cousin,*). Use **capital letters** for names, months and the first word of the closing.","examples":["Date: **December 2** / **Thursday, December 10**.","Greeting: **Dear Hamza,** / **Dear Mrs. Amal,** / **Dear Grandpa,**","Purpose (thank): **Thank you for helping us with the clean-up.**","Purpose (invite): **I am writing to invite you to our Helping Hands Day.**","Purpose (offer): **I would like to offer to water your plants while you are away.**","Detail: **My class will collect warm coats for families in need.**","Friendly ending: **Please write back soon. / I hope to see you soon.**","Closings: **Your friend, / Your cousin, / With love, / Best wishes,**","Signature: **Omar** (the writer's name under the closing)."],"common_errors":["✗ dear hamza → ✓ Dear Hamza, (Capitals + a comma after the greeting.)","✗ Your Cousin → ✓ Your cousin, (Only the first word of the closing has a capital; add a comma.)","✗ december 2 → ✓ December 2 (Months start with a capital letter.)","✗ Starting the body with 'Hi how are you what's up' → ✓ I hope you and your family are well. I am writing to invite you… (Write complete sentences and say your purpose.)","✗ Signing at the top. → ✓ Sign your name at the **end**, under the closing. (Signature comes last.)","✗ I am writing for invite you. → ✓ I am writing to invite you. (writing **to** + verb.)"],"arabic":"الرسالة الودية رسالة إلى شخص تعرفه: صديق أو قريب أو جار، ولها خمسة أجزاء بالترتيب: التاريخ ← التحية ← المتن ← الختام ← التوقيع.\n\nيبدأ المتن بالغرض (لماذا تكتب: للشكر أو الدعوة أو عرض المساعدة)، ثم التفاصيل (ماذا ومتى وأين ولماذا)، ثم جملة ودية مثل Please write back soon.\n\nالترقيم: فاصلة بعد التحية (Dear Hamza,) وبعد الختام (Your cousin,)، وحروف كبيرة لأسماء الأشخاص والشهور وأول كلمة في الختام.\n\nالتوقيع (اسم الكاتب) يأتي في النهاية تحت عبارة الختام."},"video":{"script":[{"time":"00:00–00:15","narration":"Omar wants his cousin Hamza to come to Helping Hands Day. He writes a letter!","on_screen":"A Friendly Letter ✉️","visual":"Omar at a desk with paper, an envelope and a stamp."},{"time":"00:15–01:05","narration":"December 2. Dear Hamza, I hope you and your family are well…","on_screen":"(model letter)","visual":"The letter writes itself line by line."},{"time":"01:05–01:45","narration":"Five parts: date, greeting, body, closing, signature!","on_screen":"date → greeting → body → closing → signature","visual":"Each part lights up in a different color with a label."},{"time":"01:45–02:20","narration":"The body starts with the purpose: to invite! Then the details: what, when, where.","on_screen":"Purpose → details","visual":"A target icon (purpose) then small icons for what/when/where."},{"time":"02:20–02:55","narration":"Commas after the greeting and the closing! Capitals for names and months!","on_screen":"Dear Hamza,   Your cousin,","visual":"Commas hop into place; capital letters grow."}],"captions_ar":["يريد عمر أن يأتي ابن عمه حمزة إلى يوم الأيادي المساعدة، فيكتب رسالة!","2 ديسمبر. عزيزي حمزة، أرجو أن تكون أنت وعائلتك بخير…","خمسة أجزاء: التاريخ، والتحية، والمتن، والختام، والتوقيع!","يبدأ المتن بالغرض: الدعوة! ثم التفاصيل: ماذا ومتى وأين.","فواصل بعد التحية والختام! وحروف كبيرة للأسماء والشهور!"],"voice":"Narrator: American English, warm female teacher, speed 0.90. Omar reads his letter excitedly."},"texts":[{"type":"model","title":"A Letter from Omar","body":"December 2\n\nDear Hamza,\n\nI hope you and your family are well. I am writing to invite you to our school's Helping Hands Day on Thursday, December 10.\n\nOn that day, every class will do something kind for our community. My class will collect warm coats for families in need, and we will also plant trees around the mosque. You can stay at our house, and my mother will make her famous kabsa for dinner!\n\nPlease ask your parents and write back soon. I really hope you can come.\n\nYour cousin,\n\nOmar","word_count":92,"audio_id":"AUD-RW-L03-U2-LS4-T1","id":"TXT-RW-L03-U2-LS4-1","genre":"model text","role":"model","difficulty":"350L–500L","glossary":[],"annotations":["**December 2** – the **date** goes at the top.","**Dear Hamza,** – the **greeting**: *Dear* + name + **comma**.","**I am writing to invite you…** – the first body sentence tells the **purpose** (why you are writing).","**On that day, … You can stay…** – the **details**: what, when, where and why.","**Please … write back soon.** – an ending sentence that asks for an answer.","**Your cousin,** – the **closing**: a capital letter and a **comma**.","**Omar** – the **signature**: the writer's name."]}],"activities":[{"id":"RW-L03-U2-LS4-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Choose the best answer.","instructions_ar":"اختر أفضل إجابة.","items":[{"q":"What is the purpose of Omar's letter?","answer":"to invite Hamza to Helping Hands Day","explanation":"I am writing to invite you…","explanation_ar":"دعوة حمزة.","options":["to thank Hamza for a gift","to invite Hamza to Helping Hands Day","to say sorry","to ask for money"],"dok":1,"skill":"purpose","stage":"controlled"},{"q":"Which part of Omar's letter is the greeting?","answer":"Dear Hamza,","explanation":"Dear + name + comma.","explanation_ar":"التحية.","options":["December 2","Dear Hamza,","Your cousin,","Omar"],"dok":1,"skill":"letter parts","stage":"controlled"},{"q":"Which part comes LAST in a friendly letter?","answer":"the signature","explanation":"The writer's name comes last.","explanation_ar":"التوقيع.","options":["the date","the greeting","the body","the signature"],"dok":1,"skill":"letter parts","stage":"controlled"},{"q":"Where does Omar's class plan to plant trees?","answer":"around the mosque","explanation":"Model letter body.","explanation_ar":"حول المسجد.","options":["in the school yard","at the beach","around the mosque","in Hamza's garden"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"*Please reply soon.* *Reply* means ___.","answer":"answer","explanation":"Reply = answer.","explanation_ar":"رُدّ.","options":["forget","invite","collect","answer"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"Which closing for a letter to a friend is written correctly?","answer":"Your friend,","explanation":"Capital first word + comma.","explanation_ar":"Your friend,","options":["Your friend,","your friend","Your Friend","your Friend,"],"dok":2,"skill":"punctuation","stage":"controlled"}]},{"id":"RW-L03-U2-LS4-A2","type":"sequence","stage":"guided","instructions":"Put in order: Put the letter parts in order.","instructions_ar":"رتّب أجزاء الرسالة.","items":[{"q":"Order Sami's short letter.","answer":"November 20 → Dear Grandpa, → Thank you for the palm tree. I water it every evening. → With love, → Sami","explanation":"date → greeting → body → closing → signature.","explanation_ar":"تاريخ ← تحية ← متن ← ختام ← توقيع.","stage":"guided","parts":["Thank you for the palm tree. I water it every evening.","Sami","November 20","Dear Grandpa,","With love,"],"target":["November 20","Dear Grandpa,","Thank you for the palm tree. I water it every evening.","With love,","Sami"]},{"q":"Build a greeting for Mrs. Amal.","answer":"Dear Mrs. Amal,","explanation":"Dear + title + name + comma.","explanation_ar":"Dear + اللقب + الاسم + فاصلة.","stage":"guided","parts":["Dear","Amal,","Mrs."],"target":["Dear","Mrs.","Amal,"]},{"q":"Build an invitation purpose sentence.","answer":"I am writing → to invite you → to our class party.","explanation":"Purpose sentence.","explanation_ar":"جملة الغرض.","stage":"guided","parts":["to our class party.","I am writing","to invite you"],"target":["I am writing","to invite you","to our class party."]},{"q":"Build a thank-you purpose sentence.","answer":"Thank you → for helping us → clean the park.","explanation":"Thank-you purpose sentence.","explanation_ar":"جملة غرض الشكر.","stage":"guided","parts":["for helping us","clean the park.","Thank you"],"target":["Thank you","for helping us","clean the park."]},{"q":"Build a friendly ending sentence.","answer":"Please write back soon.","explanation":"A friendly ending for the body.","explanation_ar":"جملة ودية ختامية.","stage":"guided","parts":["write back","Please","soon."],"target":["Please","write back","soon."]},{"q":"Build a closing for a letter to anyone you know.","answer":"Best wishes,","explanation":"Closing + comma.","explanation_ar":"ختام + فاصلة.","stage":"guided","parts":["wishes,","Best"],"target":["Best","wishes,"]}]},{"id":"RW-L03-U2-LS4-A3","type":"gap_fill","stage":"freer","instructions":"Freer practice: Use the word bank.","instructions_ar":"استخدم بنك الكلمات.","items":[{"q":"The ________ of my letter is to thank my teacher.","answer":"purpose","explanation":"The reason for writing.","explanation_ar":"الغرض.","stage":"freer"},{"q":"Start the letter with a ________ like 'Dear Faris,'.","answer":"greeting","explanation":"The hello part.","explanation_ar":"تحية.","stage":"freer"},{"q":"The ________ is the main part with your message.","answer":"body","explanation":"Main part.","explanation_ar":"المتن.","stage":"freer"},{"q":"Write your ________ under the closing.","answer":"signature","explanation":"Your name.","explanation_ar":"توقيعك.","stage":"freer"},{"q":"I want to ________ my friends to my birthday.","answer":"invite","explanation":"Ask to come.","explanation_ar":"أدعو.","stage":"freer"},{"q":"'Your friend,' is a ________.","answer":"closing","explanation":"Goodbye words.","explanation_ar":"عبارة ختام.","stage":"freer"}]},{"id":"RW-L03-U2-LS4-A4","type":"open","stage":"production","instructions":"Writing: Write parts of a friendly letter.","instructions_ar":"اكتب أجزاء الرسالة الودية.","items":[{"q":"Write a greeting to your teacher.","answer":"Dear Mr. Khalid,","explanation":"Dear + name + comma.","explanation_ar":"Dear + الاسم + فاصلة.","dok":1,"skill":"letter parts","stage":"production"},{"q":"Write a purpose sentence to thank a friend for a gift.","answer":"Thank you for the colorful book you gave me on Eid.","explanation":"Thank you for…","explanation_ar":"Thank you for…","dok":2,"skill":"purpose","stage":"production"},{"q":"Write two detail sentences inviting a friend to a clean-up.","answer":"The clean-up is on Saturday at nine o'clock in the park. Please bring gloves and a bottle of water.","explanation":"When, where, what to bring.","explanation_ar":"متى وأين وماذا تُحضر.","dok":2,"skill":"details","stage":"production"},{"q":"Fix this letter ending: *your friend Lama*","answer":"Your friend, (new line) Lama","explanation":"Capital + comma + signature on the next line.","explanation_ar":"حرف كبير + فاصلة + توقيع في سطر جديد.","dok":2,"skill":"editing","stage":"production"}]}],"game":{"name":"Post Office","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Mail sorter: a letter arrives in pieces; the child drags the parts into order and taps punctuation mistakes to fix them. Fixed letters fly into a mailbox.","Each team gets three envelopes.","Teams put each letter in order (date, greeting, body, closing, signature).","Teams find and fix punctuation and capital mistakes with red pens.","The 'postmaster' (teacher) checks; correct letters go in the mailbox.","Each mailed letter = 2 points; each fixed mistake = 1 point."],"data":[]},"exit_quiz":[{"q":"How many parts does a friendly letter have?","answer":"five","explanation":"date, greeting, body, closing, signature.","explanation_ar":"خمسة.","options":["two","three","five","seven"],"dok":1,"skill":"letter parts"},{"q":"Which part tells WHY you are writing?","answer":"the purpose sentence in the body","explanation":"Purpose = why.","explanation_ar":"جملة الغرض.","options":["the purpose sentence in the body","the date","the signature","the closing"],"dok":1,"skill":"purpose"},{"q":"What comes right after *Dear Hamza*?","answer":"a comma","explanation":"Greeting + comma.","explanation_ar":"فاصلة.","options":["a period","a question mark","nothing","a comma"],"dok":1,"skill":"punctuation"},{"q":"Which date about Helping Hands Day is written correctly?","answer":"December 10","explanation":"Months have capitals.","explanation_ar":"December 10.","options":["december 10","December 10","December, 10,","10 december"],"dok":1,"skill":"capitals"},{"q":"Which sentence is the best purpose sentence for an invitation?","answer":"I am writing to invite you to our Helping Hands Day.","explanation":"It tells why you write.","explanation_ar":"جملة غرض الدعوة.","options":["I like pizza.","I am writing to invite you to our Helping Hands Day.","Your cousin,","Dear Hamza,"],"dok":2,"skill":"purpose"},{"q":"Which ending sentence fits the body of a friendly letter?","answer":"Please write back soon.","explanation":"A friendly ending.","explanation_ar":"Please write back soon.","options":["Please write back soon.","Dear Omar,","December 2","The end of the story."],"dok":2,"skill":"body"},{"q":"Fix it: *dear mrs. amal*","answer":"Dear Mrs. Amal,","explanation":"Capitals + comma.","explanation_ar":"Dear Mrs. Amal,","options":["dear Mrs. Amal.","Dear mrs. amal,","Dear Mrs. Amal,","DEAR MRS. AMAL"],"dok":2,"skill":"editing"},{"q":"Why does a letter have a signature?","answer":"so the reader knows who wrote it","explanation":"Signature = writer's name.","explanation_ar":"ليعرف القارئ من الكاتب.","options":["so the reader knows who wrote it","to show the date","to make it longer","to start the letter"],"dok":2,"skill":"letter parts"},{"q":"How is a thank-you letter different from an invitation letter?","answer":"They have different purposes: to thank or to invite.","explanation":"Same parts, different purpose.","explanation_ar":"الغرض مختلف.","options":["One has no greeting.","One has no date.","They have different purposes: to thank or to invite.","They are always the same."],"dok":3,"skill":"compare"},{"q":"Which detail should Omar add to make his invitation clearer?","answer":"what time Helping Hands Day starts","explanation":"Time is an important detail.","explanation_ar":"وقت البدء.","options":["his favorite color","the name of his cat","a joke about camels","what time Helping Hands Day starts"],"dok":3,"skill":"evaluate details"}],"images":[{"id":"IMG-RW-L03-U2-LS4-V01","prompt":"Picture for the word 'greeting': a letter with 'Dear Hamza,' highlighted"},{"id":"IMG-RW-L03-U2-LS4-V02","prompt":"Picture for the word 'body': a letter with the middle paragraphs highlighted"},{"id":"IMG-RW-L03-U2-LS4-V03","prompt":"Picture for the word 'closing': a letter with 'Your cousin,' highlighted"},{"id":"IMG-RW-L03-U2-LS4-V04","prompt":"Picture for the word 'signature': a hand signing a name"},{"id":"IMG-RW-L03-U2-LS4-V05","prompt":"Picture for the word 'invite': an invitation card"},{"id":"IMG-RW-L03-U2-LS4-V06","prompt":"Picture for the word 'purpose': a dart hitting the center of a target"},{"id":"IMG-RW-L03-U2-LS4-V07","prompt":"Picture for the word 'reply': two envelopes passing between two houses"},{"id":"IMG-RW-L03-U2-LS4-01","prompt":"Omar writes a letter with five labelled parts."},{"id":"IMG-RW-L03-U2-LS4-02","prompt":"A letter outline showing five colored parts."},{"id":"IMG-RW-L03-U2-LS4-03","prompt":"Children sort letters at a pretend post office."}],"audio":[{"id":"AUD-RW-L03-U2-LS4-V01","script":"greeting. Start your letter with a greeting."},{"id":"AUD-RW-L03-U2-LS4-V02","script":"body. The body tells the reader your message."},{"id":"AUD-RW-L03-U2-LS4-V03","script":"closing. My closing is 'Your cousin,'."},{"id":"AUD-RW-L03-U2-LS4-V04","script":"signature. Write your signature under the closing."},{"id":"AUD-RW-L03-U2-LS4-V05","script":"invite. I invite you to our school event."},{"id":"AUD-RW-L03-U2-LS4-V06","script":"purpose. The purpose of my letter is to say thank you."},{"id":"AUD-RW-L03-U2-LS4-V07","script":"reply. Please reply soon."},{"id":"AUD-RW-L03-U2-LS4-T1","script":"December 2 Dear Hamza, I hope you and your family are well. I am writing to invite you to our school's Helping Hands Day on Thursday, December 10. On that day, every class will do something kind for our community. My class will collect warm coats for families in need, and we will also plant trees around the mosque. You can stay at our house, and my mother will make her famous kabsa for dinner! Please ask your parents and write back soon. I really hope you can come. Your cousin, Omar"},{"id":"AUD-RW-L03-U2-LS4-VID","script":"Omar wants his cousin Hamza to come to Helping Hands Day. He writes a letter! December 2. Dear Hamza, I hope you and your family are well… Five parts: date, greeting, body, closing, signature! The body starts with the purpose: to invite! Then the details: what, when, where. Commas after the greeting and the closing! Capitals for names and months!"}]},{"id":"RW-L03-U2-LS5","title":"Writing Workshop: A friendly letter offering help to a neighbor","lesson_type":"writing_workshop","objectives":["plan a friendly letter offering help to a neighbor with the Letter Frame","write a letter with all five parts: a purpose sentence, at least three helpful offers with details and a kind ending","revise for a polite tone, edit punctuation and publish the letter on decorated paper"],"objectives_ar":["التخطيط لرسالة ودية تعرض المساعدة على جار باستخدام إطار الرسالة.","كتابة رسالة بأجزائها الخمسة: جملة غرض وثلاثة عروض مساعدة على الأقل مع التفاصيل وخاتمة لطيفة.","التحسين لتكون النبرة مهذبة، وتدقيق الترقيم، ونشر الرسالة على ورق مزخرف."],"success_criteria":["I can write a clear purpose sentence that offers help.","I can give details: what I will do, when and how.","I can use polite words and correct letter punctuation."],"success_criteria_ar":["أستطيع كتابة جملة غرض واضحة تعرض المساعدة.","أستطيع إعطاء تفاصيل: ماذا سأفعل ومتى وكيف.","أستطيع استخدام كلمات مهذبة وترقيم الرسالة الصحيح."],"map_area":"Language Usage: Write, Revise Texts for Purpose and Audience (cross-strand)","vocabulary":[{"word":"neighbor","pos":"noun","ipa":"/ˈneɪbər/","definition":"a person who lives near you","arabic":"جار","example":"Mr. Hamdan is our neighbor.","image_id":"IMG-RW-L03-U2-LS5-V01","audio_id":"AUD-RW-L03-U2-LS5-V01","tier":"core"},{"word":"polite","pos":"adjective","ipa":"/pəˈlaɪt/","definition":"speaking and acting in a kind, respectful way","arabic":"مهذّب","example":"Please and thank you are polite words.","image_id":"IMG-RW-L03-U2-LS5-V02","audio_id":"AUD-RW-L03-U2-LS5-V02","tier":"core"},{"word":"would like to","pos":"phrase","ipa":"/wʊd laɪk tu/","definition":"a polite way to say 'want to'","arabic":"أودّ أن","example":"I would like to help you.","image_id":"IMG-RW-L03-U2-LS5-V03","audio_id":"AUD-RW-L03-U2-LS5-V03","tier":"core"},{"word":"errand","pos":"noun","ipa":"/ˈɛrənd/","definition":"a short trip to buy or do something for someone","arabic":"مشوار / مهمة قصيرة","example":"I can run errands for you.","image_id":"IMG-RW-L03-U2-LS5-V04","audio_id":"AUD-RW-L03-U2-LS5-V04","tier":"core"},{"word":"recover","pos":"verb","ipa":"/rɪˈkʌvər/","definition":"to get better after being sick or hurt","arabic":"يتعافى","example":"I hope you recover soon.","image_id":"IMG-RW-L03-U2-LS5-V05","audio_id":"AUD-RW-L03-U2-LS5-V05","tier":"core"},{"word":"available","pos":"adjective","ipa":"/əˈveɪləbəl/","definition":"free to do something","arabic":"متاح / متفرّغ","example":"I am available every afternoon.","image_id":"IMG-RW-L03-U2-LS5-V06","audio_id":"AUD-RW-L03-U2-LS5-V06","tier":"core"},{"word":"knock","pos":"verb","ipa":"/nɑk/","definition":"to hit a door gently to say you are there","arabic":"يطرق (الباب)","example":"Knock on our door if you need anything.","image_id":"IMG-RW-L03-U2-LS5-V07","audio_id":"AUD-RW-L03-U2-LS5-V07","tier":"core"}],"explanation":{"text":"In this letter, your **purpose** is to **offer help** to a neighbor. Say it clearly near the start: *I would like to help you while your leg gets better.*\n\nGive **at least three offers** with **details**: **what** you will do, **when** and **how**. Use polite language: **I would like to…, I can…, Please…, I hope…**\n\nEnd the body kindly: tell the neighbor how to **contact** you (*Knock on our door…*) and wish them well. Then add the **closing** and **signature**. Use the **Letter Frame** to plan.","examples":["Date: **January 12**","Greeting: **Dear Mr. Hamdan,**","Purpose: **I am sorry that you hurt your leg. I would like to help you until you recover.**","Offer 1 + details: **I can bring your newspaper from the gate every morning before school.**","Offer 2 + details: **I can also water your roses on Monday and Thursday afternoons.**","Offer 3 + details: **If you need anything from the shop, my brother and I can run errands for you.**","Kind ending: **Please knock on our door if you need help. I hope you feel better soon.**","Closing + signature: **Your neighbor, / Layla**","More offer ideas: read a story aloud, carry shopping, feed a pet, help with the phone, visit and drink tea."],"common_errors":["✗ I will do everything for you. → ✓ I can bring your newspaper every morning before school. (Give **specific** offers with details.)","✗ You need help. → ✓ I would like to help you. (Be **polite**: offer, don't order.)","✗ I can watering your roses. → ✓ I can water your roses. (After **can**, use the base verb.)","✗ I would like help you. → ✓ I would like to help you. (would like **to** + verb.)","✗ Your Neighbor Layla → ✓ Your neighbor, (new line) Layla (Comma after the closing; name on the next line.)","✗ I hope you recover soon!!! → ✓ I hope you recover soon. (One period or one exclamation mark is enough.)"],"arabic":"غرضك في هذه الرسالة هو عرض المساعدة على جارك؛ قل ذلك بوضوح في البداية: I would like to help you…\n\nقدّم ثلاثة عروض على الأقل مع التفاصيل: ماذا ستفعل ومتى وكيف، واستخدم لغة مهذبة: I would like to, I can, Please, I hope.\n\nاختم المتن بلطف: أخبر جارك كيف يتواصل معك وتمنَّ له الخير، ثم أضف الختام والتوقيع.\n\nخطّط باستخدام إطار الرسالة: التحية ← الغرض ← التفاصيل ← الختام ← الاسم."},"video":{"script":[{"time":"00:00–00:20","narration":"Mr. Hamdan next door hurt his leg. Layla wants to help – she writes a letter!","on_screen":"A Letter Offering Help","visual":"Layla looks from her window at Mr. Hamdan on crutches watering his roses with difficulty."},{"time":"00:20–00:55","narration":"Plan with the Letter Frame: greeting, purpose, details, closing, name.","on_screen":"1 Plan – Letter Frame","visual":"A frame fills with Layla's notes and small drawings."},{"time":"00:55–01:55","narration":"January 12. Dear Mr. Hamdan, I am sorry that you hurt your leg. I would like to help you…","on_screen":"2 Draft – purpose + 3 offers","visual":"Each offer appears with an icon: newspaper, watering can, shopping bag."},{"time":"01:55–02:20","narration":"Revise: Is every offer clear and polite? 'I will do everything' – too general! 'I can bring your newspaper every morning' – clear!","on_screen":"3 Revise – specific + polite","visual":"A vague sentence fades; a specific one glows."},{"time":"02:20–02:40","narration":"Edit: commas after the greeting and closing, capitals, can + verb.","on_screen":"4 Edit , A can + verb","visual":"Commas pop into place."},{"time":"02:40–03:00","narration":"Publish: Layla decorates her letter with roses and slides it under Mr. Hamdan's door.","on_screen":"5 Publish 💌","visual":"Mr. Hamdan reads the letter and smiles."}],"captions_ar":["أصيب جارنا السيد حمدان في ساقه. تريد ليلى أن تساعده، فتكتب رسالة!","خطّط بإطار الرسالة: التحية، الغرض، التفاصيل، الختام، الاسم.","12 يناير. عزيزي السيد حمدان، يؤسفني أنك أصبت في ساقك. أودّ أن أساعدك…","التحسين: هل كل عرض واضح ومهذب؟","التدقيق: الفواصل بعد التحية والختام، والحروف الكبيرة، وcan مع الفعل.","النشر: تزيّن ليلى رسالتها بالورود وتضعها تحت باب السيد حمدان."],"voice":"Narrator: American English, warm female teacher, speed 0.90. Layla (the Artist) reads her letter kindly."},"texts":[],"activities":[{"id":"RW-L03-U2-LS5-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Choose the best answer.","instructions_ar":"اختر أفضل إجابة.","items":[{"q":"Which purpose sentence offers help politely?","answer":"I would like to help you until your leg gets better.","explanation":"Polite offer.","explanation_ar":"عرض مهذب.","options":["You must let me help you.","I would like to help you until your leg gets better.","Your leg is broken.","I am busy every day."],"dok":1,"skill":"purpose","stage":"controlled"},{"q":"Which offer to Mr. Hamdan is the most specific?","answer":"I can bring your newspaper every morning before school.","explanation":"What + when.","explanation_ar":"عرض محدد.","options":["I will help you.","I can do things.","Maybe I will come.","I can bring your newspaper every morning before school."],"dok":2,"skill":"details","stage":"controlled"},{"q":"*I hope you recover soon.* *Recover* means ___.","answer":"get better","explanation":"Recover = get better.","explanation_ar":"تتعافى.","options":["get worse","go shopping","get better","move house"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"A short trip to buy something for someone is an ___.","answer":"errand","explanation":"Errand = short trip/job.","explanation_ar":"مشوار.","options":["envelope","signature","errand","event"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"Which sentence about the roses uses *can* correctly?","answer":"I can water your roses.","explanation":"can + base verb.","explanation_ar":"can + فعل مجرد.","options":["I can watering your roses.","I can water your roses.","I can to water your roses.","I cans water your roses."],"dok":1,"skill":"grammar","stage":"controlled"},{"q":"Which kind ending fits a letter offering help?","answer":"Please knock on our door if you need anything.","explanation":"A friendly contact line.","explanation_ar":"نهاية لطيفة.","options":["Please knock on our door if you need anything.","Dear Mr. Hamdan,","January 12","Your neighbor,"],"dok":2,"skill":"body","stage":"controlled"}]},{"id":"RW-L03-U2-LS5-A2","type":"sequence","stage":"guided","instructions":"Put in order: Put the parts or words in order.","instructions_ar":"رتّب الأجزاء أو الكلمات.","items":[{"q":"Order the parts of Layla's letter.","answer":"January 12 → Dear Mr. Hamdan, → I would like to help you until you recover. → Your neighbor, → Layla","explanation":"date → greeting → body → closing → signature.","explanation_ar":"الترتيب الصحيح.","stage":"guided","parts":["January 12","Layla","I would like to help you until you recover.","Your neighbor,","Dear Mr. Hamdan,"],"target":["January 12","Dear Mr. Hamdan,","I would like to help you until you recover.","Your neighbor,","Layla"]},{"q":"Build a purpose sentence for a neighbor who is traveling.","answer":"I would like → to help you → while you are away.","explanation":"Polite purpose sentence.","explanation_ar":"جملة غرض مهذبة.","stage":"guided","parts":["I would like","while you are away.","to help you"],"target":["I would like","to help you","while you are away."]},{"q":"Build an offer about a pet.","answer":"I can feed → your cat → every evening.","explanation":"Offer + what + when.","explanation_ar":"عرض + ماذا + متى.","stage":"guided","parts":["every evening.","I can feed","your cat"],"target":["I can feed","your cat","every evening."]},{"q":"Build a second offer.","answer":"I can also → carry your shopping → from the car.","explanation":"Offer + also + how.","explanation_ar":"عرض + also + كيف.","stage":"guided","parts":["from the car.","carry your shopping","I can also"],"target":["I can also","carry your shopping","from the car."]},{"q":"Build a good wish.","answer":"I hope you feel better soon.","explanation":"Good wish.","explanation_ar":"أمنية طيبة.","stage":"guided","parts":["better soon.","you feel","I hope"],"target":["I hope","you feel","better soon."]},{"q":"Build a closing for a letter to a neighbor.","answer":"Your neighbor,","explanation":"Closing + comma.","explanation_ar":"ختام + فاصلة.","stage":"guided","parts":["neighbor,","Your"],"target":["Your","neighbor,"]}]},{"id":"RW-L03-U2-LS5-A3","type":"organizer","stage":"freer","instructions":"Organizer: Plan your letter with the Letter Frame.","instructions_ar":"خطط لرسالتك بإطار الرسالة.","items":[{"q":"Who is your neighbor, and why might they need help? Write the greeting and purpose.","answer":"Dear Mrs. Sara, I would like to help you with your new baby.","explanation":"Greeting + purpose.","explanation_ar":"تحية + غرض.","dok":1,"skill":"planning","stage":"freer"},{"q":"Write notes for three offers (what, when, how).","answer":"carry shopping – after school; play with her son – Saturday; bring bread – every morning","explanation":"Three offers.","explanation_ar":"ثلاثة عروض.","dok":2,"skill":"planning","stage":"freer"},{"q":"Write your kind ending: how to contact you and a good wish.","answer":"Please call my mother if you need us. I hope your baby sleeps well!","explanation":"Contact + wish.","explanation_ar":"تواصل + أمنية.","dok":2,"skill":"planning","stage":"freer"},{"q":"Write your closing and signature.","answer":"Your neighbor, Faris","explanation":"Closing + name.","explanation_ar":"ختام + اسم.","dok":1,"skill":"planning","stage":"freer"}]},{"id":"RW-L03-U2-LS5-A4","type":"writing","stage":"production","instructions":"Writing: Write, revise, edit and publish your letter.","instructions_ar":"اكتب رسالتك وحسّنها ودققها وانشرها.","items":[{"q":"Write the date, greeting and purpose sentence.","answer":"January 12 / Dear Mr. Hamdan, / I am sorry that you hurt your leg. I would like to help you until you recover.","explanation":"Three parts.","explanation_ar":"ثلاثة أجزاء.","dok":2,"skill":"writing","stage":"production"},{"q":"Write three offers with details.","answer":"I can bring your newspaper every morning before school. I can also water your roses on Monday and Thursday afternoons. My brother and I can run errands for you.","explanation":"Specific offers.","explanation_ar":"عروض محددة.","dok":2,"skill":"writing","stage":"production"},{"q":"Write your kind ending, closing and signature.","answer":"Please knock on our door if you need help. I hope you feel better soon. / Your neighbor, / Layla","explanation":"Ending + closing + name.","explanation_ar":"نهاية + ختام + اسم.","dok":2,"skill":"writing","stage":"production"},{"q":"Which offer did you make more specific after Pairs Check? Write it before and after.","answer":"Before: I will help you. After: I can water your roses on Monday and Thursday afternoons.","explanation":"Before → after.","explanation_ar":"قبل ← بعد.","dok":3,"skill":"revising","stage":"production","_w":{"checklist":[],"min":null,"max":null}}]},{"id":"RW-L03-U2-LS5-ORG","type":"organizer","organizer":"Letter Frame","instructions":"Organizer: Plan each part of your letter. Write short notes, not full sentences.","items":[{"q":"Date","answer":"January 12"},{"q":"Greeting (Dear …,)","answer":"Dear Mr. Hamdan,"},{"q":"Purpose (why I am writing)","answer":"sorry about your leg – I would like to help until you recover"},{"q":"Offer 1 – what, when, how","answer":"newspaper from the gate – every morning before school"},{"q":"Offer 2 – what, when, how","answer":"water the roses – Monday and Thursday afternoons"},{"q":"Offer 3 – what, when, how","answer":"errands to the shop with my brother – when you need"},{"q":"Kind ending (how to contact me + good wish)","answer":"knock on our door; I hope you feel better soon"},{"q":"Closing + name","answer":"Your neighbor, Layla"}]},{"id":"RW-L03-U2-LS5-WR","type":"writing","instructions":"Writing: Write a friendly letter to a neighbor offering help. Include all five parts, a purpose sentence, at least three specific offers and a kind ending. Write a friendly letter to a neighbor offering help. Include all five parts, a purpose sentence, at least three specific offers and a kind ending.","instructions_ar":"اكتب رسالة ودية إلى جار تعرض فيها المساعدة، فيها الأجزاء الخمسة وجملة غرض وثلاثة عروض محددة على الأقل وخاتمة لطيفة.","prompt":"Write a friendly letter to a neighbor offering help. Include all five parts, a purpose sentence, at least three specific offers and a kind ending.","checklist":["My letter has a date, greeting, body, closing and signature.","My purpose sentence offers help.","I wrote at least three offers with details (what, when, how).","I used polite words (I would like to, I can, please, I hope).","I used can + base verb correctly.","I put commas after the greeting and the closing.","I used capital letters for names and months."],"rubric_id":"RW-RUBRIC-5T","min_words":70,"max_words":150,"organizer":"Letter Frame (greeting → purpose → details → closing → name)","items":[{"q":"Write a friendly letter to a neighbor offering help. Include all five parts, a purpose sentence, at least three specific offers and a kind ending.","answer":"January 12 / Dear Mr. Hamdan, / I am sorry that you hurt your leg. I would like to help you until you recover. I can bring your newspaper from the gate every morning before school. I can also water your roses on Monday and Thursday afternoons. If you need anything from the shop, my brother and I can run errands for you. Please knock on our door if you need help. I hope you feel better soon. / Your neighbor, / Layla","_w":{"checklist":["My letter has a date, greeting, body, closing and signature.","My purpose sentence offers help.","I wrote at least three offers with details (what, when, how).","I used polite words (I would like to, I can, please, I hope).","I used can + base verb correctly.","I put commas after the greeting and the closing.","I used capital letters for names and months."],"min":70,"max":150}}]}],"game":{"name":"Kindness Match","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Kind neighbor: a house door opens to show a neighbor's need; the child chooses the best specific offer and taps the polite starter (I would like to… / I can…). Each good match lights a lamp in the street.","Teams get the neighbor cards and a pile of offer cards.","For each neighbor, choose the two best offers (specific + helpful).","Put vague offers ('I will help.') in the 'Make it better' pile.","Teams improve one vague offer and read their best offer aloud politely.","Good match = 1 point; improved offer = 2 points."],"data":[]},"exit_quiz":[{"q":"What is the purpose of the letter in this lesson?","answer":"to offer help to a neighbor","explanation":"Offering help.","explanation_ar":"عرض المساعدة على جار.","options":["to offer help to a neighbor","to invite a cousin to a party","to say sorry for being late","to describe an animal"],"dok":1,"skill":"purpose"},{"q":"A person who lives near you is your ___.","answer":"neighbor","explanation":"Neighbor = lives near you.","explanation_ar":"جارك.","options":["teacher","neighbor","cousin","volunteer"],"dok":1,"skill":"vocabulary"},{"q":"Which phrase is a POLITE way to say *want to*?","answer":"would like to","explanation":"would like to = polite want.","explanation_ar":"would like to.","options":["would like to","must","have to","never"],"dok":1,"skill":"polite language"},{"q":"*I am available every afternoon.* *Available* means ___.","answer":"free to do something","explanation":"Available = free.","explanation_ar":"متاح.","options":["very tired","far away","not polite","free to do something"],"dok":1,"skill":"vocabulary"},{"q":"Which offer gives WHAT and WHEN?","answer":"I can water your plants on Monday afternoons.","explanation":"What + when.","explanation_ar":"ماذا + متى.","options":["I can help.","I can water your plants on Monday afternoons.","Plants are green.","I like your house."],"dok":2,"skill":"details"},{"q":"Which offer about errands is grammatically correct?","answer":"My brother and I can run errands for you.","explanation":"can + base verb.","explanation_ar":"صحيحة.","options":["My brother and I can running errands for you.","My brother and me can to run errands.","My brother and I cans run errands.","My brother and I can run errands for you."],"dok":2,"skill":"grammar"},{"q":"Which closing and signature are correct?","answer":"Your neighbor, / Layla","explanation":"Capital + comma, then name.","explanation_ar":"صحيحة.","options":["your neighbor / layla","Your Neighbor. / Layla","Your neighbor Layla,","Your neighbor, / Layla"],"dok":2,"skill":"punctuation"},{"q":"Why should offers be specific?","answer":"So the neighbor knows exactly what you will do and when.","explanation":"Specific = clear.","explanation_ar":"ليعرف الجار بالضبط ماذا ستفعل ومتى.","options":["So the neighbor knows exactly what you will do and when.","So the letter is shorter.","So you can skip the purpose.","So you don't need a signature."],"dok":2,"skill":"evaluate"},{"q":"Your letter says *You need help.* How can you make it more polite?","answer":"I would like to help you.","explanation":"Offer, don't order.","explanation_ar":"I would like to help you.","options":["Help is needed by you.","You must take my help.","I would like to help you.","Help!"],"dok":3,"skill":"revising"},{"q":"Which letter offering help is the most complete?","answer":"five parts, a purpose sentence, three specific offers and a kind ending","explanation":"It has every part.","explanation_ar":"الأكثر اكتمالًا.","options":["a greeting and one vague offer","a drawing with no words","five parts, a purpose sentence, three specific offers and a kind ending","a list of chores with no greeting"],"dok":3,"skill":"evaluate"}],"images":[{"id":"IMG-RW-L03-U2-LS5-V01","prompt":"Picture for the word 'neighbor': two houses side by side with people waving"},{"id":"IMG-RW-L03-U2-LS5-V02","prompt":"Picture for the word 'polite': a child bowing slightly and smiling"},{"id":"IMG-RW-L03-U2-LS5-V03","prompt":"Picture for the word 'would like to': a child raising a hand politely"},{"id":"IMG-RW-L03-U2-LS5-V04","prompt":"Picture for the word 'errand': a child carrying a bag from a small shop"},{"id":"IMG-RW-L03-U2-LS5-V05","prompt":"Picture for the word 'recover': a man with a leg cast smiling"},{"id":"IMG-RW-L03-U2-LS5-V06","prompt":"Picture for the word 'available': a calendar with free afternoons highlighted"},{"id":"IMG-RW-L03-U2-LS5-V07","prompt":"Picture for the word 'knock': a hand knocking on a door"},{"id":"IMG-RW-L03-U2-LS5-01","prompt":"Layla slides a decorated letter under her neighbor's door."},{"id":"IMG-RW-L03-U2-LS5-02","prompt":"A letter frame organizer with sections for each part."},{"id":"IMG-RW-L03-U2-LS5-03","prompt":"Four neighbors who might need help."}],"audio":[{"id":"AUD-RW-L03-U2-LS5-V01","script":"neighbor. Mr. Hamdan is our neighbor."},{"id":"AUD-RW-L03-U2-LS5-V02","script":"polite. Please and thank you are polite words."},{"id":"AUD-RW-L03-U2-LS5-V03","script":"would like to. I would like to help you."},{"id":"AUD-RW-L03-U2-LS5-V04","script":"errand. I can run errands for you."},{"id":"AUD-RW-L03-U2-LS5-V05","script":"recover. I hope you recover soon."},{"id":"AUD-RW-L03-U2-LS5-V06","script":"available. I am available every afternoon."},{"id":"AUD-RW-L03-U2-LS5-V07","script":"knock. Knock on our door if you need anything."},{"id":"AUD-RW-L03-U2-LS5-VID","script":"Mr. Hamdan next door hurt his leg. Layla wants to help – she writes a letter! Plan with the Letter Frame: greeting, purpose, details, closing, name. January 12. Dear Mr. Hamdan, I am sorry that you hurt your leg. I would like to help you… Revise: Is every offer clear and polite? 'I will do everything' – too general! 'I can bring your newspaper every morning' – clear! Edit: commas after the greeting and closing, capitals, can + verb. Publish: Layla decorates her letter with roses and slides it under Mr. Hamdan's door."}]}],"unit_test":[{"q":"People who help at the hospital for free are ___.","answer":"volunteers","explanation":"Help for free = volunteers.","explanation_ar":"متطوعون.","options":["charities","volunteers","neighbors only","signatures"],"dok":1,"skill":"vocabulary","_part":"Part A – Vocabulary"},{"q":"Our school will ___ books to children who have none.","answer":"donate","explanation":"Give to help = donate.","explanation_ar":"تتبرّع.","options":["frown","recover","knock","donate"],"dok":1,"skill":"vocabulary","_part":"Part A – Vocabulary"},{"q":"Grandpa is 85. He is an ___ man.","answer":"elderly","explanation":"Old (polite) = elderly.","explanation_ar":"مسنّ.","options":["available","elderly","useless","polite"],"dok":1,"skill":"vocabulary","_part":"Part A – Vocabulary"},{"q":"Thank you for the gift! I am very ___.","answer":"grateful","explanation":"Thankful = grateful.","explanation_ar":"ممتن.","options":["careless","helpless","grateful","fearless"],"dok":1,"skill":"vocabulary","_part":"Part A – Vocabulary"},{"q":"Which word means *without care*?","answer":"careless","explanation":"-less = without.","explanation_ar":"careless.","options":["careless","careful","caring","cared"],"dok":1,"skill":"suffixes","_part":"Part A – Vocabulary"},{"q":"*The old phone does not work. It is useless.* *Useless* means ___.","answer":"it has no use","explanation":"use + less.","explanation_ar":"لا فائدة منه.","options":["it has no use","it is very useful","it is colorful","it is new"],"dok":2,"skill":"suffixes in context","_part":"Part A – Vocabulary"},{"q":"Which -ful word in this list is spelled correctly?","answer":"thankful","explanation":"-ful has one l.","explanation_ar":"thankful.","options":["thankfull","thankfol","thanksfull","thankful"],"dok":1,"skill":"spelling","_part":"Part A – Vocabulary"},{"q":"*The new boy was **fearless**; he jumped into the pool first.* What does *fearless* mean?","answer":"without fear","explanation":"fear + less.","explanation_ar":"بلا خوف.","options":["full of fear","very tired","without fear","very kind"],"dok":2,"skill":"suffixes in context","_part":"Part A – Vocabulary"},{"q":"Which greeting for a letter to Mr. Khalid is correct?","answer":"Dear Mr. Khalid,","explanation":"Capitals + comma.","explanation_ar":"صحيحة.","options":["dear mr. khalid","Dear Mr. Khalid.","Dear Mr. Khalid,","DEAR MR. KHALID"],"dok":1,"skill":"letter punctuation","_part":"Part D – Letter skills"},{"q":"Which part of a letter tells WHY you are writing?","answer":"the purpose sentence in the body","explanation":"Purpose = why.","explanation_ar":"جملة الغرض.","options":["the date","the signature","the closing","the purpose sentence in the body"],"dok":1,"skill":"letter parts","_part":"Part D – Letter skills"},{"q":"Put these in order: (1) Your friend, (2) Dear Lama, (3) June 5 (4) Sami (5) Thank you for the book.","answer":"3, 2, 5, 1, 4","explanation":"date → greeting → body → closing → signature.","explanation_ar":"3، 2، 5، 1، 4.","options":["2, 3, 5, 4, 1","3, 5, 2, 1, 4","2, 5, 3, 1, 4","3, 2, 5, 1, 4"],"dok":2,"skill":"letter format","_part":"Part D – Letter skills"},{"q":"Which offer to a neighbor with a dog is the most specific?","answer":"I can walk your dog every afternoon after school.","explanation":"What + when.","explanation_ar":"عرض محدد.","options":["I can help.","I can walk your dog every afternoon after school.","I will do things for you.","Maybe I can come."],"dok":2,"skill":"details","_part":"Part D – Letter skills"},{"q":"Which sentence about watering is polite and correct?","answer":"I would like to water your plants.","explanation":"would like to + verb.","explanation_ar":"صحيحة ومهذبة.","options":["I would like water your plants.","I would like to watering your plants.","I would like to water your plants.","You must let me water your plants."],"dok":2,"skill":"polite language","_part":"Part D – Letter skills"},{"q":"Which closing for a letter to your grandmother is written correctly?","answer":"With love,","explanation":"Capital first word + comma.","explanation_ar":"With love,","options":["With love,","with love","With Love.","with Love,"],"dok":1,"skill":"letter punctuation","_part":"Part D – Letter skills"}],"unit_writing":{"task":"Imagine you are Sami. Write a friendly letter to the boy in the photo who is wearing your blue jacket. Include all five parts. In the body, say why you are writing, tell him something about the jacket and offer one more way to help.","model":"December 20 / Dear friend, / I saw your photo, and I was so happy to see you in my blue jacket! My grandfather gave me that jacket, and it kept me warm every winter. Now I hope it keeps you warm in the mountains. Please wear it on cold mornings when you walk to school. My class wants to help again, so we will collect books for your school next month. Please write back and tell me what books you like. / Your friend, / Sami","marks":20}});
